/** All translations for zizhitongjian ch.027 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起昭陽太淵獻，盡玄黓涒灘，凡十年。", literal: "From Zhaoyang Taiyuanxian through Xuanqi Tunshan; ten years in all.", idiomatic: "From Zhaoyang Taiyuanxian through Xuanqi Tunshan—ten years in all." },
  { zh: "1春，二月，以鳳皇、甘露降集京師，赦天下。", literal: "1. In spring, the second month, because phoenixes and sweet dew descended and gathered at the capital, a general amnesty was proclaimed.", idiomatic: "1. In spring, the second month, because phoenixes and sweet dew descended upon the capital, the empire was pardoned." },
  { zh: "----2穎川太守黃霸在郡前後八年，政事愈治；", literal: "----2 Huang Ba, governor of Yingchuan, had been in the commandery eight years in all; administration grew ever better governed;", idiomatic: "----2 Huang Ba, governor of Yingchuan, had governed the commandery eight years in all; administration grew ever sounder;" },
  { zh: "是時鳳皇、神爵數集郡國，穎川尤多。", literal: "at that time phoenixes and divine finches repeatedly gathered in commanderies and kingdoms, and Yingchuan had especially many.", idiomatic: "at that time phoenixes and divine finches repeatedly gathered across the realm, and Yingchuan had especially many." },
  { zh: "夏，四月，詔曰：「穎川太守霸，宣佈詔令，百姓嚮化，孝子、弟弟、貞婦、順孫日以眾多，田者讓畔，道不拾遺，養視鰥寡，贍助貧窮，獄或八年亡重罪囚，其賜爵關內侯、黃金百斤、秩中二千石。", literal: "In summer, the fourth month, an edict said: \"Huang Ba, governor of Yingchuan, has proclaimed and spread imperial edicts; the people have turned toward transformation. Filial sons, respectful younger brothers, chaste wives, and obedient grandsons grow more numerous day by day; plowmen yield field boundaries, none pick up lost things on the road, orphans and widows are cared for, the poor are supported and aided, and in the prisons for eight years there have been no prisoners of serious crimes. He is granted the rank of Marquis within the Passes, a hundred jin of gold, and salary of zhong erqian shi.\"", idiomatic: "In summer, the fourth month, an edict said: \"Huang Ba, governor of Yingchuan, has proclaimed and spread imperial edicts; the people have turned toward virtue. Filial sons, respectful younger brothers, chaste wives, and obedient grandsons grow more numerous day by day; plowmen yield field boundaries, none pick up lost things on the road, orphans and widows are cared for, the poor are supported, and in the prisons for eight years there have been no prisoners of serious crimes. Grant him the rank of Marquis within the Passes, a hundred jin of gold, and salary of zhong erqian shi.\"" },
  { zh: "」而穎川孝、弟、有行義民、三老、力田皆以差賜爵及帛。", literal: "\" Moreover, filial sons, younger brothers, men of righteous conduct, village elders, and champion farmers of Yingchuan were all granted ranks and silks by gradation.", idiomatic: "\" Moreover, filial sons, younger brothers, men of righteous conduct, village elders, and champion farmers of Yingchuan were all granted ranks and silks by gradation." },
  { zh: "後數月，征霸為太子太傅。", literal: "Several months later, Ba was summoned to be Grand Tutor to the Heir Apparent.", idiomatic: "Several months later, Ba was summoned to serve as Grand Tutor to the Heir Apparent." },
  { zh: "----3五月，匈奴單于遣弟呼留若王勝之來朝。", literal: "----3 In the fifth month, the Xiongnu chanyu sent his younger brother Huluruo Wang Shengzhi to attend court.", idiomatic: "----3 In the fifth month, the Xiongnu chanyu sent his younger brother Huluruo Wang Shengzhi to attend court." },
  { zh: "----4冬，十月，鳳皇十一集杜陵。", literal: "----4 In winter, the tenth month, eleven phoenixes gathered at Duling.", idiomatic: "----4 In winter, the tenth month, eleven phoenixes gathered at Duling." },
  { zh: "----5河南太守東海嚴延年為治陰鷙酷烈，眾人所謂當死者一朝出之，所謂當生者詭殺之，吏民莫能測其意深淺，戰慄不敢犯禁。", literal: "----5 Yan Yannian of Donghai, governor of Henan, governed with hidden severity and fierce cruelty: those the multitude said should die he released in a morning; those they said should live he killed by trickery. Officials and people alike could not gauge the depth or shallowness of his intent; trembling, they dared not violate his prohibitions.", idiomatic: "----5 Yan Yannian of Donghai, governor of Henan, governed with hidden severity and fierce cruelty: those the multitude said should die he released in a morning; those they said should live he killed by trickery. Officials and people alike could not gauge his intent; trembling, they dared not violate his prohibitions." },
  { zh: "冬月，傳屬縣囚會論府上，流血數里，河南號曰「屠伯」。", literal: "In the winter months he summoned county prisoners to be tried together at the prefectural seat; blood flowed for several li. Henan called him the \"Butcher Lord.\"", idiomatic: "In winter he summoned county prisoners to be tried together at the prefectural seat; blood flowed for several li. Henan called him the \"Butcher Lord.\"" },
  { zh: "延年素輕黃霸為人，及比郡為守，褒賞反在己前，心內不服。", literal: "Yannian had long looked down on Huang Ba as a man; when a neighboring commandery had him as governor, praise and rewards came before his own, and inwardly he would not submit.", idiomatic: "Yannian had long looked down on Huang Ba; when a neighboring commandery had him as governor, praise and rewards came before his own, and inwardly he would not submit." },
  { zh: "河南界中又有蝗蟲，府丞義出行蝗，還，見延年。", literal: "Within Henan's borders there were also locusts; Assistant Prefect Yi went out to drive off locusts, returned, and saw Yannian.", idiomatic: "Within Henan's borders locusts appeared; Assistant Prefect Yi went out to drive them off, returned, and saw Yannian." },
  { zh: "延年曰：「此蝗豈鳳皇食邪？", literal: "Yannian said: \"Are these locusts perhaps food for phoenixes?", idiomatic: "Yannian said: \"Are these locusts perhaps food for phoenixes?" },
  { zh: "」義年老，頗悖，素畏延年，恐見中傷。", literal: "\" Yi was old and rather contrary; he had long feared Yannian and dreaded being struck at and harmed.", idiomatic: "\" Yi was old and rather contrary; he had long feared Yannian and dreaded being struck at and harmed." },
  { zh: "延年本嘗與義俱為丞相史，實親厚之，饋遺之甚厚。", literal: "Yannian had once served together with Yi as clerks to the chancellor and had truly been close and thick with him, sending him very generous gifts.", idiomatic: "Yannian had once served with Yi as clerks to the chancellor and had truly been close to him, sending him very generous gifts." },
  { zh: "義愈益恐，自筮，得死卦，忽忽不樂，取告至長安，上書言延年罪名十事；", literal: "Yi grew ever more fearful, divined for himself, and obtained the death hexagram; restless and unhappy, he took leave to Chang'an and submitted a memorial listing ten charges against Yannian;", idiomatic: "Yi grew ever more fearful, divined for himself, and obtained the death hexagram; restless and unhappy, he took leave to Chang'an and submitted a memorial listing ten charges against Yannian;" },
  { zh: "已拜奏，因飲藥自殺，以明不欺。", literal: "after the memorial had been presented he drank poison and killed himself, to show he did not deceive.", idiomatic: "after the memorial had been presented he drank poison and killed himself, to show he did not deceive." },
  { zh: "事下御史丞按驗，得其語言怨望、誹謗政治數事。", literal: "The matter was sent down to the Vice Censor-in-Chief for investigation and verification; they obtained several matters of his words showing resentment and slandering the government.", idiomatic: "The matter was sent down to the Vice Censor-in-Chief for investigation; they obtained several matters of his words showing resentment and slandering the government." },
  { zh: "十一月，延年坐不道，棄市。", literal: "In the eleventh month, Yannian was convicted of impiety and executed in the marketplace.", idiomatic: "In the eleventh month, Yannian was convicted of impiety and executed in the marketplace." },
  { zh: "初，延年母從東海來，欲從延年臘。", literal: "Earlier, Yannian's mother came from Donghai, wishing to keep the year-end sacrifice with Yannian.", idiomatic: "Earlier, Yannian's mother came from Donghai, wishing to keep the year-end sacrifice with Yannian." },
  { zh: "到洛陽，適見報囚，母大驚，便止都亭，不肯入府。", literal: "Reaching Luoyang, she happened to see the report of prisoners; the mother was greatly alarmed, stopped at the capital post station, and would not enter the prefectural offices.", idiomatic: "Reaching Luoyang, she happened to see the report of prisoners; the mother was greatly alarmed, stopped at the capital post station, and would not enter the prefectural offices." },
  { zh: "延年出至都亭謁母，母閉閣不見。", literal: "Yannian went out to the post station to pay respects to his mother; the mother shut the door and would not see him.", idiomatic: "Yannian went out to the post station to pay respects to his mother; the mother shut the door and would not see him." },
  { zh: "延年免冠頓首閣下，良久，母乃見之，因數責延年：「幸得備郡守，專治千里，不聞仁愛教化，有以全安愚民。", literal: "Yannian removed his cap and knocked his head at the door for a long time before the mother at last saw him, and thereupon repeatedly reproached Yannian: \"You were fortunate enough to serve as commandery governor, with sole charge of a thousand li, yet I hear nothing of benevolent love and transforming instruction by which to preserve and secure foolish commoners.", idiomatic: "Yannian removed his cap and knocked his head at the door for a long time before the mother at last saw him, and thereupon repeatedly reproached Yannian: \"You were fortunate enough to serve as commandery governor, with sole charge of a thousand li, yet I hear nothing of benevolent love and transforming instruction by which to preserve and secure foolish commoners." },
  { zh: "顧乘刑罰，多刑殺人，欲以立威，豈為民父母意哉！", literal: "Instead you rely on punishments, putting many to death by punishment, wishing thereby to establish awe—how is this the intent of parents to the people!", idiomatic: "Instead you rely on punishments, putting many to death, wishing thereby to establish awe—how is this the intent of parents to the people!" },
  { zh: "」延年服罪，重頓首謝，因自為母御歸府舍。", literal: "\" Yannian acknowledged guilt, knocked his head again in thanks, and thereupon himself drove the carriage for his mother back to the official residence.", idiomatic: "\" Yannian acknowledged guilt, knocked his head again in thanks, and thereupon himself drove the carriage for his mother back to the official residence." },
  { zh: "母畢正臘，謂延年曰：「天道神明，人不可獨殺。", literal: "When the mother had finished the proper year-end sacrifice, she said to Yannian: \"Heaven's Way is divine and bright; a man must not kill alone.", idiomatic: "When the mother had finished the proper year-end sacrifice, she said to Yannian: \"Heaven's Way is divine and bright; a man must not kill alone." },
  { zh: "我不意當老見壯子被刑戮也！", literal: "I never thought I would grow old only to see my strong son subjected to punishment and execution!", idiomatic: "I never thought I would grow old only to see my strong son subjected to punishment and execution!" },
  { zh: "行矣，去汝東歸，掃除墓地耳！", literal: "Go! Leave you and return east—I have only to sweep the graveyard!", idiomatic: "Go! Leave you and return east—I have only to sweep the graveyard!" },
  { zh: "」遂去，歸郡，見昆弟、宗人，復為言之。", literal: "\" She thereupon left, returned to the commandery, saw brothers and clansmen, and spoke of it again.", idiomatic: "\" She thereupon left, returned to the commandery, saw brothers and clansmen, and spoke of it again." },
  { zh: "後歲餘，果敗，東海莫不賢智其母。", literal: "More than a year later he indeed fell; in Donghai none failed to regard his mother as worthy and wise.", idiomatic: "More than a year later he indeed fell; in Donghai none failed to regard his mother as worthy and wise." },
  { zh: "----6匈奴握衍朐鞮單于暴虐，好殺伐，國中不附。", literal: "----6 The Xiongnu chanyu Woyu Jodi was violent and cruel, fond of killing and campaigning; within the state none adhered to him.", idiomatic: "----6 The Xiongnu chanyu Woyu Jodi was violent and cruel, fond of killing and campaigning; within the state none adhered to him." },
  { zh: "及太子、左賢王數讒左地貴人，左地貴人皆怨。", literal: "The Heir Apparent and the Left Worthy King repeatedly slandered the nobles of the left territory; the nobles of the left territory all bore resentment.", idiomatic: "The Heir Apparent and the Left Worthy King repeatedly slandered the nobles of the left territory; the nobles of the left territory all bore resentment." },
  { zh: "會烏桓擊匈奴東邊姑夕王，頗得人民，單于怒。", literal: "It happened that the Wuhuan struck the Xiongnu eastern-side Guxi King and took quite a number of people; the chanyu was enraged.", idiomatic: "It happened that the Wuhuan struck the Xiongnu eastern-side Guxi King and took quite a number of people; the chanyu was enraged." },
  { zh: "姑夕王恐，即與烏禪幕及左地貴人共立稽侯狦為呼韓邪單于，發左地兵四五萬人，西擊握衍朐鞮單于，至姑且水北。", literal: "The Guxi King was afraid and at once joined Wuchanmu and the nobles of the left territory in installing Ji Houyu as Chanyu Huhanye, raising forty or fifty thousand troops of the left territory and striking west against Chanyu Woyu Jodi, reaching north of the Guxi River.", idiomatic: "The Guxi King was afraid and at once joined Wuchanmu and the nobles of the left territory in installing Ji Houyu as Chanyu Huhanye, raising forty or fifty thousand troops of the left territory and striking west against Chanyu Woyu Jodi, reaching north of the Guxi River." },
  { zh: "未戰，握衍朐鞮單于兵敗走，使人報其弟右賢王曰：「匈奴共攻我，若肯發兵助我乎？", literal: "Before battle was joined, Chanyu Woyu Jodi's army was defeated and fled; he sent a man to report to his younger brother the Right Worthy King, saying: \"The Xiongnu are all attacking me—will you be willing to raise troops and aid me?", idiomatic: "Before battle was joined, Chanyu Woyu Jodi's army was defeated and fled; he sent a man to report to his younger brother the Right Worthy King, saying: \"The Xiongnu are all attacking me—will you be willing to raise troops and aid me?" },
  { zh: "」右賢王曰：「若不愛人，殺昆弟、諸貴人。", literal: "\" The Right Worthy King said: \"You do not love men—you have killed brothers and the various nobles.", idiomatic: "\" The Right Worthy King said: \"You do not love men—you have killed brothers and the various nobles." },
  { zh: "各自死若處，無來污我！", literal: "Each die in your own place—do not come to defile me!", idiomatic: "Each die in your own place—do not come to defile me!" },
  { zh: "」握衍朐鞮單于恚，自殺。", literal: "\" Chanyu Woyu Jodi, enraged, killed himself.", idiomatic: "\" Chanyu Woyu Jodi, enraged, killed himself." },
  { zh: "左大且渠都隆奇亡之右賢王所，其民眾盡降呼韓邪單于。", literal: "The Left Grand Commandant Dulongqi fled to the Right Worthy King's place; his people all surrendered to Chanyu Huhanye.", idiomatic: "The Left Grand Commandant Dulongqi fled to the Right Worthy King's place; his people all surrendered to Chanyu Huhanye." },
  { zh: "呼韓邪單于歸庭；", literal: "Chanyu Huhanye returned to the court;", idiomatic: "Chanyu Huhanye returned to the court;" },
  { zh: "數月，罷兵，使各歸故地，乃收其兄呼屠吾斯在民間者，立為左谷蠡王，使人告右賢貴人，欲令殺右賢王，其冬，都隆奇與右賢王共立日逐王薄胥堂為屠耆單于，發兵數萬人東襲呼韓邪單于，呼韓邪單于兵敗走。", literal: "several months later he dismissed the armies and sent each back to his former territory; he then gathered his elder brother Hutuwusi, who was among the people, and installed him as Left Guli King, and sent a man to tell the Right Worthy nobles, wishing to have the Right Worthy King killed. That winter, Dulongqi and the Right Worthy King jointly installed the Rizhu King Boxutang as Chanyu Tujue, raised an army of several tens of thousands, and struck east against Chanyu Huhanye; Chanyu Huhanye's army was defeated and fled.", idiomatic: "several months later he dismissed the armies and sent each back to his former territory; he then gathered his elder brother Hutuwusi, who was among the people, and installed him as Left Guli King, and sent a man to tell the Right Worthy nobles, wishing to have the Right Worthy King killed. That winter, Dulongqi and the Right Worthy King jointly installed the Rizhu King Boxutang as Chanyu Tujue, raised an army of several tens of thousands, and struck east against Chanyu Huhanye; Chanyu Huhanye's army was defeated and fled." },
  { zh: "屠耆單于還，以其長子都塗吾西為左谷蠡王，少子姑瞀樓頭為右谷蠡王，留居單于庭。", literal: "Chanyu Tujue returned, made his eldest son Dutuwuxi Left Guli King and his younger son Gumoloutou Right Guli King, and remained dwelling at the chanyu court.", idiomatic: "Chanyu Tujue returned, made his eldest son Dutuwuxi Left Guli King and his younger son Gumoloutou Right Guli King, and remained dwelling at the chanyu court." },
  { zh: "1春，正月，上幸甘泉，郊泰畤。", literal: "1. In spring, the first month, the emperor favored Sweet Springs and sacrificed at the border to the Great Altar.", idiomatic: "1. In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "----2皇太子冠。", literal: "----2 The Imperial Heir Apparent received the capping.", idiomatic: "----2 The Imperial Heir Apparent received the capping." },
  { zh: "----3秋，匈奴屠耆單于使先賢撣兄右奧鞬王與烏藉都尉各二萬騎屯東方，以備呼韓邪單于。", literal: "----3 In autumn, the Xiongnu chanyu Tujue sent the Right Aojian King, elder brother of the Xianxian chanyu, and the Wujie Commandant, each with twenty thousand horse, to garrison in the east against Chanyu Huhanye.", idiomatic: "----3 In autumn, the Xiongnu chanyu Tujue sent the Right Aojian King, elder brother of the Xianxian chanyu, and the Wujie Commandant, each with twenty thousand horse, to garrison in the east against Chanyu Huhanye." },
  { zh: "是時西方呼揭王來與唯犁當戶謀，共讒右賢王。", literal: "At that time the Western Hujie King came and plotted with Weili Danghu, jointly slandering the Right Worthy King,", idiomatic: "At that time the Western Hujie King came and plotted with Weili Danghu, jointly slandering the Right Worthy King," },
  { zh: "言欲自立為單于。", literal: "saying he wished to install himself as chanyu.", idiomatic: "saying he wished to install himself as chanyu." },
  { zh: "屠耆單于殺右賢王父子，後知其冤，復殺唯犁當戶。", literal: "Chanyu Tujue killed the Right Worthy King and his son; later learning it was unjust, he killed Weili Danghu as well.", idiomatic: "Chanyu Tujue killed the Right Worthy King and his son; later learning it was unjust, he killed Weili Danghu as well." },
  { zh: "於是呼揭王恐，遂畔去，自立為呼揭單于。", literal: "Thereupon the Hujie King was afraid, turned rebel and left, and installed himself as Chanyu Hujie.", idiomatic: "Thereupon the Hujie King was afraid, rebelled and left, and installed himself as Chanyu Hujie." },
  { zh: "右奧鞬王聞之，即自立為車犁單于。", literal: "The Right Aojian King heard of it and at once installed himself as Chanyu Chelí.", idiomatic: "The Right Aojian King heard of it and at once installed himself as Chanyu Chelí." },
  { zh: "烏藉都尉亦自立為烏藉單于。", literal: "The Wujie Commandant also installed himself as Chanyu Wujie.", idiomatic: "The Wujie Commandant also installed himself as Chanyu Wujie." },
  { zh: "凡五單于。", literal: "In all there were five chanyus.", idiomatic: "In all there were five chanyus." },
  { zh: "屠耆單于自將兵東擊車犁單于，使都隆奇擊烏藉。", literal: "Chanyu Tujue himself led troops east to strike Chanyu Chelí and sent Dulongqi to strike Wujie.", idiomatic: "Chanyu Tujue himself led troops east to strike Chanyu Chelí and sent Dulongqi to strike Wujie." },
  { zh: "烏藉、車犁皆敗，西北走，與呼揭單于兵合為四萬人。", literal: "Wujie and Chelí were both defeated and fled northwest; their troops joined with Chanyu Hujie's forces to make forty thousand men.", idiomatic: "Wujie and Chelí were both defeated and fled northwest; their troops joined with Chanyu Hujie's forces to make forty thousand men." },
  { zh: "烏藉、呼揭皆去單于號，共並力尊輔車犁單于。", literal: "Wujie and Hujie both cast off the title of chanyu and jointly with united strength honored and supported Chanyu Chelí.", idiomatic: "Wujie and Hujie both cast off the title of chanyu and jointly honored and supported Chanyu Chelí." },
  { zh: "屠耆單于聞之，使左大將、都尉將四萬騎分屯東方，以備呼韓邪單于，自將四萬騎西擊車犁單于。", literal: "Chanyu Tujue heard of it and sent the Left Grand General and Commandant with forty thousand horse to garrison separately in the east against Chanyu Huhanye; he himself led forty thousand horse west to strike Chanyu Chelí.", idiomatic: "Chanyu Tujue heard of it and sent the Left Grand General and Commandant with forty thousand horse to garrison separately in the east against Chanyu Huhanye; he himself led forty thousand horse west to strike Chanyu Chelí." },
  { zh: "車犁單于敗，西北走。", literal: "Chanyu Chelí was defeated and fled northwest.", idiomatic: "Chanyu Chelí was defeated and fled northwest." },
  { zh: "屠耆單于即引兵西南留闟敦地。", literal: "Chanyu Tujue thereupon led his troops southwest and halted at Tadun.", idiomatic: "Chanyu Tujue thereupon led his troops southwest and halted at Tadun." },
  { zh: "漢議者多曰：「匈奴為害日久，可因其壞亂，舉兵滅之。", literal: "Many among the Han deliberators said: \"The Xiongnu have been a harm for long; we may take advantage of their breakdown and disorder and raise troops to destroy them.", idiomatic: "Many among the Han deliberators said: \"The Xiongnu have been a harm for long; we may take advantage of their breakdown and disorder and raise troops to destroy them." },
  { zh: "」詔問御史大夫蕭望之，對曰：「《春秋》，晉士匄帥師侵齊，聞齊侯卒，引師而還，君子大其不伐喪，以為恩足以服孝子，誼足以動諸侯。", literal: "\" The emperor ordered inquiry of Censor-in-Chief Xiao Wangzhi, who answered: \"In the Spring and Autumn Annals, Shi Gai of Jin led troops to invade Qi; hearing that the Marquis of Qi had died, he led his army back. The noble man greatly praised his not attacking during mourning, holding that grace suffices to win filial sons and righteousness suffices to move the feudal lords.", idiomatic: "\" The emperor ordered inquiry of Censor-in-Chief Xiao Wangzhi, who answered: \"In the Spring and Autumn Annals, Shi Gai of Jin led troops to invade Qi; hearing that the Marquis of Qi had died, he led his army back. The noble man greatly praised his not attacking during mourning, holding that grace suffices to win filial sons and righteousness suffices to move the feudal lords." },
  { zh: "前單于慕化嚮善，稱弟，遣使請求和親，海內欣然，夷狄莫不聞。", literal: "The former chanyu admired transformation and turned toward goodness, called himself younger brother, and sent envoys requesting peace through marriage; within the seas all rejoiced, and none among the barbarians failed to hear.", idiomatic: "The former chanyu admired transformation and turned toward goodness, called himself younger brother, and sent envoys requesting peace through marriage; within the seas all rejoiced, and none among the barbarians failed to hear." },
  { zh: "未終奉約，不幸為賊臣所殺；", literal: "Before he had finished fulfilling the covenant, he was unfortunately killed by treacherous ministers;", idiomatic: "Before he had finished fulfilling the covenant, he was unfortunately killed by treacherous ministers;" },
  { zh: "今而伐之，是乘亂而幸災也，彼必奔走遠遁。", literal: "to attack them now is to ride disorder and rejoice in disaster; they will surely flee in flight to distant places.", idiomatic: "to attack them now is to ride disorder and rejoice in disaster; they will surely flee to distant places." },
  { zh: "不以義動兵，恐勞而無功。", literal: "To move troops without righteousness—I fear toil without achievement.", idiomatic: "To move troops without righteousness—I fear toil without achievement." },
  { zh: "宜遣使者弔問，輔其微弱，救其災患。", literal: "It is fitting to dispatch envoys to offer condolences and inquiry, assist their weakness, and relieve their disasters and afflictions.", idiomatic: "It is fitting to dispatch envoys to offer condolences, assist their weakness, and relieve their disasters." },
  { zh: "四夷聞之，咸貴中國之仁義。", literal: "When the four barbarians hear of it, all will esteem the Middle Kingdom's benevolence and righteousness.", idiomatic: "When the four barbarians hear of it, all will esteem the Middle Kingdom's benevolence and righteousness." },
  { zh: "如遂蒙恩得復其位，必稱臣服從，此德之盛之。", literal: "If he then receives grace and regains his position, he will surely declare submission and obedience—this is the fullness of virtue.\"", idiomatic: "If he then receives grace and regains his position, he will surely declare submission and obedience—this is the fullness of virtue.\"" },
  { zh: "」上從其議。", literal: "\" The emperor followed his counsel.", idiomatic: "\" The emperor followed his counsel." },
  { zh: "----4冬，十有二月，乙酉朔，日有食之。", literal: "----4 In winter, the twelfth month, on the first day of the month yiyou, there was a solar eclipse.", idiomatic: "----4 In winter, the twelfth month, on the first day of the month yiyou, there was a solar eclipse." },
  { zh: "----5韓延壽代蕭望之為左馮翊。", literal: "----5 Han Yannian replaced Xiao Wangzhi as Left Governor of Feng.", idiomatic: "----5 Han Yannian replaced Xiao Wangzhi as Left Governor of Feng." },
  { zh: "望之聞延壽在東郡時放散官錢千餘萬，使御史案之。", literal: "Wangzhi heard that while Yannian was in Dong commandery he had dispersed more than ten million in official funds and had the censor investigate.", idiomatic: "Wangzhi heard that while Yannian was in Dong commandery he had dispersed more than ten million in official funds and had the censor investigate." },
  { zh: "延壽聞知，即部吏案校望之在馮翊時廩犧官錢放散百餘萬。", literal: "Yannian heard of it and at once had his clerks investigate and verify that while Wangzhi was in Feng more than a million in granary and sacrificial official funds had been dispersed.", idiomatic: "Yannian heard of it and at once had his clerks investigate and verify that while Wangzhi was in Feng more than a million in granary and sacrificial official funds had been dispersed." },
  { zh: "望之自奏：「職在總領天下，聞事不敢不問，而為延壽所拘持。", literal: "Wangzhi himself memorialized: \"My duty is to oversee all under Heaven; hearing of matters I dare not fail to inquire—yet I am seized and held by Yannian.", idiomatic: "Wangzhi himself memorialized: \"My duty is to oversee all under Heaven; hearing of matters I dare not fail to inquire—yet I am seized and held by Yannian." },
  { zh: "」上由是不直延壽，各令窮竟所考。", literal: "\" The emperor thereupon did not side with Yannian and ordered each to pursue to the end what was investigated.", idiomatic: "\" The emperor thereupon did not side with Yannian and ordered each to pursue to the end what was investigated." },
  { zh: "望之卒無事實。", literal: "Wangzhi in the end had no substantiated matter.", idiomatic: "Wangzhi in the end had no substantiated matter." },
  { zh: "而望之遣御史案東郡者，得其試騎士日奢僭逾制；", literal: "But the censor Wangzhi had sent to investigate Dong commandery found that on days of cavalry trials he was extravagant and transgressed regulations;", idiomatic: "But the censor Wangzhi had sent to investigate Dong commandery found that on days of cavalry trials he was extravagant and transgressed regulations;" },
  { zh: "又取官銅物，候月食鑄刀劍，效尚方事；", literal: "moreover he took official copper goods and, watching for lunar eclipses, cast swords and blades, imitating the Imperial Workshop;", idiomatic: "moreover he took official copper goods and, watching for lunar eclipses, cast swords and blades, imitating the Imperial Workshop;" },
  { zh: "及取官錢帛私假徭使吏；", literal: "and took official money and silks to lend privately for corvée labor and employ clerks;", idiomatic: "and took official money and silks to lend privately for corvée labor and employ clerks;" },
  { zh: "及治飾車甲三百萬以上。", literal: "and in repairing and adorning chariots and armor spent more than three million.", idiomatic: "and in repairing and adorning chariots and armor spent more than three million." },
  { zh: "延壽竟坐狡猾不道，棄市。", literal: "Yannian in the end was convicted of cunning impiety and executed in the marketplace.", idiomatic: "Yannian in the end was convicted of cunning impiety and executed in the marketplace." },
  { zh: "吏民數千人送至渭城，老小扶持車轂，爭奏酒炙。", literal: "Several thousand officials and commoners escorted him to Weicheng; old and young supported his carriage hubs and vied to present wine and roasted meat.", idiomatic: "Several thousand officials and commoners escorted him to Weicheng; old and young supported his carriage hubs and vied to present wine and roasted meat." },
  { zh: "延壽不忍距逆，人人為飲，計飲酒石餘。", literal: "Yannian could not bear to refuse them; each man he made drink, and the wine consumed amounted to more than a shi.", idiomatic: "Yannian could not bear to refuse them; each man he made drink, and the wine consumed amounted to more than a shi." },
  { zh: "使掾、史分謝送者：「遠苦吏民，延壽死無所恨！", literal: "He had his clerks and secretaries thank the escorts in turn: \"You have come far and troubled officials and people—Yannian dies without regret!", idiomatic: "He had his clerks and secretaries thank the escorts in turn: \"You have come far and troubled officials and people—Yannian dies without regret!" },
  { zh: "」百姓莫不流涕。", literal: "\" The common people none failed to shed tears.", idiomatic: "\" The common people none failed to shed tears." },
  { zh: "1春，正月，上幸甘泉，郊泰畤。", literal: "1. In spring, the first month, the emperor favored Sweet Springs and sacrificed at the border to the Great Altar.", idiomatic: "1. In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "----2車騎將軍韓增薨。", literal: "----2 General of Chariots and Cavalry Han Zeng died.", idiomatic: "----2 General of Chariots and Cavalry Han Zeng died." },
  { zh: "五月，將軍許延壽為大司馬、車騎大將軍。", literal: "In the fifth month, General Xu Yannian became Grand Marshal and Grand General of Chariots and Cavalry.", idiomatic: "In the fifth month, General Xu Yannian became Grand Marshal and Grand General of Chariots and Cavalry." },
  { zh: "----3丞相丙吉年老，上重之。", literal: "----3 Chancellor Bing Ji was old in years; the emperor greatly esteemed him.", idiomatic: "----3 Chancellor Bing Ji was old in years; the emperor greatly esteemed him." },
  { zh: "蕭望之意常輕吉，上由是不悅。", literal: "Xiao Wangzhi's mind often looked lightly on Ji; the emperor was thereby displeased.", idiomatic: "Xiao Wangzhi often looked lightly on Ji; the emperor was thereby displeased." },
  { zh: "丞相司直奏望之遇丞相禮節倨慢，又使吏買賣，私所附益凡十萬三千，請逮捕系治。", literal: "The Chancellor's Direct Investigator memorialized that in meeting the chancellor Wangzhi's ritual and deportment were arrogant and slow, and that he also had clerks buy and sell, with private additions totaling one hundred three thousand, requesting arrest and imprisonment for trial.", idiomatic: "The Chancellor's Direct Investigator memorialized that in meeting the chancellor Wangzhi's ritual and deportment were arrogant and slow, and that he also had clerks buy and sell, with private additions totaling one hundred three thousand, requesting arrest and imprisonment for trial." },
  { zh: "秋，八月，壬午，詔左遷望之為太子太傅；", literal: "In autumn, the eighth month, on the day renwu, an edict demoted Wangzhi to Grand Tutor to the Heir Apparent;", idiomatic: "In autumn, the eighth month, on the day renwu, an edict demoted Wangzhi to Grand Tutor to the Heir Apparent;" },
  { zh: "以太子太傅黃霸為御史大夫。", literal: "Grand Tutor to the Heir Apparent Huang Ba was made Censor-in-Chief.", idiomatic: "Grand Tutor to the Heir Apparent Huang Ba was made Censor-in-Chief." },
  { zh: "----4匈奴呼韓邪單于遣其弟右谷蠡王等西襲屠耆單于屯兵，殺略萬餘人。", literal: "----4 The Xiongnu chanyu Huhanye sent his younger brother the Right Guli King and others west to strike the garrison troops of Chanyu Tujue, killing and carrying off more than ten thousand.", idiomatic: "----4 The Xiongnu chanyu Huhanye sent his younger brother the Right Guli King and others west to strike the garrison troops of Chanyu Tujue, killing and carrying off more than ten thousand." },
  { zh: "屠耆單于聞之，即自將六萬騎擊呼韓邪單于。", literal: "Chanyu Tujue heard of it and at once himself led sixty thousand horse to strike Chanyu Huhanye.", idiomatic: "Chanyu Tujue heard of it and at once himself led sixty thousand horse to strike Chanyu Huhanye." },
  { zh: "屠耆單于兵敗，自殺。", literal: "Chanyu Tujue's army was defeated and he killed himself.", idiomatic: "Chanyu Tujue's army was defeated and he killed himself." },
  { zh: "都隆奇乃與屠耆少子右谷蠡王姑瞀樓頭亡歸漢。", literal: "Dulongqi thereupon fled with Tujue's younger son the Right Guli King Gumoloutou and returned to Han.", idiomatic: "Dulongqi thereupon fled with Tujue's younger son the Right Guli King Gumoloutou and returned to Han." },
  { zh: "車犁單于東降呼韓邪單于。", literal: "Chanyu Chelí submitted in the east to Chanyu Huhanye.", idiomatic: "Chanyu Chelí submitted in the east to Chanyu Huhanye." },
  { zh: "冬，十一月，呼韓邪單于左大將烏厲屈與父呼遫累烏厲溫敦皆見匈奴亂，率其眾數萬人降漢；", literal: "In winter, the eleventh month, Chanyu Huhanye's Left Grand General Wuliju and his father Huzhilei Wuliwendun, both seeing the Xiongnu in disorder, led their multitudes of several tens of thousands to surrender to Han;", idiomatic: "In winter, the eleventh month, Chanyu Huhanye's Left Grand General Wuliju and his father Huzhilei Wuliwendun, both seeing the Xiongnu in disorder, led their multitudes of several tens of thousands to surrender to Han;" },
  { zh: "封烏厲屈為新城侯，烏厲溫敦為義陽侯。", literal: "Wuliju was enfeoffed as Marquis of Xincheng and Wuliwendun as Marquis of Yiyang.", idiomatic: "Wuliju was enfeoffed as Marquis of Xincheng and Wuliwendun as Marquis of Yiyang." },
  { zh: "是時李陵子復立烏藉都尉為單于，呼韓邪單于捕斬之；", literal: "At this time Li Ling's son again installed the Wuji Colonel as Chanyu; Chanyu Huhanye captured and beheaded him;", idiomatic: "At this time Li Ling's son again installed the Wuji Colonel as Chanyu; Chanyu Huhanye captured and beheaded him;" },
  { zh: "遂復都單于庭，然眾裁數萬人。", literal: "he thereupon restored the capital at the Chanyu's court, yet his followers numbered only several tens of thousands.", idiomatic: "He thereupon restored the Chanyu's court as capital, yet his followers numbered only several tens of thousands." },
  { zh: "屠耆單于從弟休旬王自立為閏振單于，在西邊；", literal: "Chanyu Tuji's younger brother by the female line, King Xiuxun, established himself as Chanyu Runzhen on the western border;", idiomatic: "Chanyu Tuji's younger brother by the female line, King Xiuxun, established himself as Chanyu Runzhen in the west;" },
  { zh: "呼韓邪單于兄左賢王呼屠吾斯亦自立為郅支骨都侯單于，在東邊。", literal: "Chanyu Huhanye's elder brother, the Left Wise King Hutuwusi, also established himself as Chanyu Zhizhi Gudu-hou on the eastern border.", idiomatic: "Chanyu Huhanye's elder brother, the Left Wise King Hutuwusi, also established himself as Chanyu Zhizhi Gudu-hou in the east." },
  { zh: "----5光祿勳平通侯楊惲，廉潔無私；", literal: "----5 Director of the Gentlemen of the Palace, Marquis of Pingtong Yang Yun, was incorrupt and selfless;", idiomatic: "----5 Director of the Gentlemen of the Palace, Marquis of Pingtong Yang Yun, was incorrupt and selfless;" },
  { zh: "然伐其行能，又性刻害，好發人陰伏，由是多怨於朝廷。", literal: "yet he vaunted his conduct and ability, and by nature was harsh and injurious, delighting in exposing people's hidden faults—thereby he incurred much resentment at court.", idiomatic: "yet he vaunted his conduct and ability, was by nature harsh and injurious, and delighted in exposing people's hidden faults—thereby incurring much resentment at court." },
  { zh: "與太僕戴長樂相失。", literal: "He fell out with the Grand Coachman Dai Changle.", idiomatic: "He fell out with Grand Coachman Dai Changle." },
  { zh: "人有上書告長樂罪，長樂疑惲教人告之，亦上書告惲罪曰：「惲上書訟韓延壽，郎中丘常謂惲曰：『聞君侯訟韓馮翊，當得活乎？", literal: "Someone submitted a memorial accusing Changle of crime; Changle suspected Yun had taught the man to accuse him and also submitted a memorial accusing Yun, saying: \"Yun submitted a memorial suing Han Yanshou. Gentleman Qiu Chang said to Yun: 'I hear the Lord sued Governor of Han, Fengyi—will he live?", idiomatic: "Someone memorialized accusing Changle of crime; Changle suspected Yun had instigated it and also memorialized accusing Yun, saying, \"Yun submitted a memorial suing Han Yanshou. Gentleman Qiu Chang said to Yun, 'I hear you sued Governor of Han, Fengyi—will he live?" },
  { zh: "』惲曰：『事何容易，脛脛者未必全也！", literal: "' Yun said: 'How easy is the matter! One with skinny shins may not necessarily be preserved whole!", idiomatic: "' Yun said, 'How easy is that! A man with skinny shins may not come through whole!" },
  { zh: "我不能自保，真人所謂「鼠不容穴，銜窶數」者也。", literal: "I cannot preserve myself—what the true man called \"a mouse cannot tolerate a hole, holding poverty in its mouth.\"", idiomatic: "I cannot save myself—what the sage called 'a mouse cannot tolerate a hole, holding poverty in its mouth.'" },
  { zh: "』又語長樂曰：『正月以來，天陰不雨，此《春秋》所記，夏侯君所言。", literal: "' He also said to Changle: 'Since the first month, the sky has been overcast without rain—this is what the Spring and Autumn records, what Lord Xiahou spoke of.", idiomatic: "' He also told Changle, 'Since the first month the sky has been overcast without rain—this is what the Spring and Autumn records, what Lord Xiahou said." },
  { zh: "』」事下廷尉。", literal: "'\" The matter was sent down to the Minister of Justice.", idiomatic: "'\" The matter was sent to the Minister of Justice." },
  { zh: "廷尉定國奏惲怨望，為妖惡言，大逆不道。", literal: "Minister of Justice Dingguo memorialized that Yun harbored resentment, uttered evil and perverse words, and committed great impiety.", idiomatic: "Minister of Justice Dingguo reported that Yun harbored resentment, uttered evil and perverse words, and committed great impiety." },
  { zh: "上不忍加誅，有詔皆免惲、長樂為庶人。", literal: "The emperor could not bear to add execution and issued an edict that both Yun and Changle be dismissed as commoners.", idiomatic: "The emperor could not bear to execute them and decreed that both Yun and Changle be dismissed as commoners." },
  { zh: "1春，正月，癸卯，博陽定侯丙吉薨。", literal: "1. Spring, first month, day guimao: Marquis Ding of Boyang Bing Ji died.", idiomatic: "1. In spring, the first month, on day guimao, Marquis Ding of Boyang Bing Ji died." },
  { zh: ":班固贊曰：古之制名，必由象類，遠取諸物，近取諸身。", literal: ": Ban Gu's praise says: In antiquity naming was made necessarily from images and categories—taking from distant things, taking from the near body.", idiomatic: ": Ban Gu writes in praise: In antiquity names were fashioned from images and categories—drawing from distant things and from the body itself." },
  { zh: "故《經》謂君為元首，臣為股肱，明其一體，相待而成也。", literal: "Therefore the Classic calls the ruler the head and limbs, ministers the thighs and arms—making clear they are one body, mutually relying to be completed.", idiomatic: "Therefore the Classic calls the ruler the head and limbs and ministers the thighs and arms—making clear they are one body that rely on each other to be whole." },
  { zh: "是故君臣相配，古今常道，自然之勢也。", literal: "Therefore ruler and ministers match each other—the constant way of past and present, the natural tendency.", idiomatic: "Therefore ruler and ministers match each other—the constant way of past and present and the natural order." },
  { zh: "近觀漢相，高祖開基，蕭、曹為冠；", literal: "Observing Han chancellors near at hand: Gaozu opened the foundation, Xiao and Cao were foremost;", idiomatic: "Observing Han chancellors at hand: Gaozu laid the foundation, and Xiao and Cao were foremost;" },
  { zh: "孝宣中興，丙、魏有聲。", literal: "Emperor Xiao's restoration, Bing and Wei had renown.", idiomatic: "In Emperor Xuan's restoration, Bing and Wei won renown." },
  { zh: "是時黜陟有序，眾職修理，公卿多稱其位，海內興於禮讓。", literal: "At that time promotion and demotion were orderly, the multitude of offices well maintained, ministers and grandees mostly filled their posts, and within the seas courtesy and yielding flourished.", idiomatic: "At that time promotion and demotion were orderly, offices well maintained, ministers and grandees mostly filled their posts, and courtesy and yielding flourished throughout the realm." },
  { zh: "覽其行事，豈虛虖哉！", literal: "Reviewing their conduct—was it empty indeed!", idiomatic: "Review their conduct—was it empty indeed!" },
  { zh: "----2二月，壬辰，黃霸為丞相。", literal: "----2 Second month, day renchen: Huang Ba became chancellor.", idiomatic: "----2 In the second month, on day renchen, Huang Ba became chancellor." },
  { zh: "霸材長於治民，及為丞相，功名損於治郡。", literal: "Ba's talent lay in governing the people; when he became chancellor, his fame and achievement fell short of governing a commandery.", idiomatic: "Ba excelled at governing the people; as chancellor his fame and achievement fell short of his record as commandery governor." },
  { zh: "時京兆尹張敞捨鶡雀飛集丞相府，霸以為神雀，議欲以聞。", literal: "At that time Metropolitan Governor Zhang Chang's lodging had a magpie fly and gather at the chancellor's residence; Ba took it for a divine bird and deliberated wishing to report it.", idiomatic: "At that time Metropolitan Governor Zhang Chang had a magpie from his lodging fly to the chancellor's residence; Ba took it for a divine bird and considered reporting it." },
  { zh: "敞奏霸曰：「竊見丞相請與中二千石、博士雜問郡、國上計長史、守丞為民興利除害，成大化，條其對。", literal: "Chang memorialized to Ba, saying: \"Your servant has seen the chancellor request to join with ranked officials at two thousand shi and academicians in mixed questioning of the commandery and state annual-report chief clerks and administrators on benefiting the people and removing harm, accomplishing great transformation, and itemizing their replies.", idiomatic: "Chang memorialized to Ba, \"Your servant has seen the chancellor request to join ranked officials at two thousand shi and academicians in questioning the commandery and state annual-report chief clerks and administrators on benefiting the people and removing harm, accomplishing great transformation, and itemizing their replies." },
  { zh: "有耕者讓畔，男女異路，道不拾遺。", literal: "There were farmers yielding field boundaries, men and women on separate roads, and no picking up lost things on the road.", idiomatic: "There were farmers yielding field boundaries, men and women on separate roads, and no picking up lost things on the road." },
  { zh: "及舉孝子、貞婦者為一輩，先上殿；", literal: "Those who presented filial sons and chaste wives formed one class and entered the hall first;", idiomatic: "Those who presented filial sons and chaste wives formed one class and entered the hall first;" },
  { zh: "舉而不知其人數者，次之；", literal: "those who presented them without knowing the persons' names came next;", idiomatic: "those who presented them without knowing the persons' names came next;" },
  { zh: "不為條教者在後。", literal: "those who did not make regulations and teachings came last.", idiomatic: "those who did not make regulations and teachings came last." },
  { zh: "叩頭謝丞相，雖口不言，而心欲其為之也。", literal: "They kowtowed and thanked the chancellor; though the mouth did not speak, the heart wished them to do it.", idiomatic: "They kowtowed and thanked the chancellor; though they did not speak aloud, they wished in their hearts to do it." },
  { zh: "長史、守丞對時，臣敞舍有鶡雀飛止丞相府屋上，丞相以下見者數百人。", literal: "When the chief clerks and administrators replied, your servant Chang's lodging had a magpie fly and perch on the chancellor's residence roof; from the chancellor down, those who saw it numbered several hundred.", idiomatic: "When the chief clerks and administrators replied, a magpie from your servant Chang's lodging flew and perched on the chancellor's roof; from the chancellor down, several hundred people saw it." },
  { zh: "邊吏多知鶡雀者，問之，皆陽不知。", literal: "Many frontier officials knew magpies; when asked, all pretended not to know.", idiomatic: "Many frontier officials knew magpies; when asked, all pretended ignorance." },
  { zh: "丞相圖議上奏曰：『臣問上計長史、守丞以興化條，皇天報下神爵。", literal: "The chancellor drafted deliberation to memorialize upward, saying: 'Your servant questioned the annual-report chief clerks and administrators on items for promoting transformation—August Heaven responded by sending down the divine bird.", idiomatic: "The chancellor drafted a memorial saying, 'Your servant questioned the annual-report chief clerks and administrators on items for promoting transformation—August Heaven responded by sending down the divine bird." },
  { zh: "』後知從臣敞舍來，乃止。", literal: "' Later learning it came from your servant Chang's lodging, he stopped.", idiomatic: "' Learning later it came from your servant Chang's lodging, he stopped." },
  { zh: "郡國吏竊笑丞相仁厚有知略，微信奇怪也。", literal: "Commandery and state officials privately laughed that the chancellor, though benevolent and thick and possessed of knowledge and strategy, still slightly believed in the strange.", idiomatic: "Commandery and state officials privately laughed that the chancellor, though benevolent and wise, still slightly believed in the strange." },
  { zh: "臣敞非敢毀丞相也，誠恐群臣莫白，而長史、守丞畏丞相指，歸捨法令，各為私教，務相增加，澆淳散樸，並行偽貌，有名亡實，傾搖解怠，甚者為妖。", literal: "Your servant Chang does not dare destroy the chancellor—he truly fears the ministers will not speak plainly, while chief clerks and administrators, fearing the chancellor's intent, return and set aside laws and ordinances, each making private teachings, striving to outdo one another, watering down purity and scattering simplicity, all practicing false appearances, having name without substance, leaning and wavering in slackness, and in extreme cases becoming demonic.", idiomatic: "Your servant Chang does not dare slander the chancellor—he truly fears the ministers will not speak plainly, while chief clerks and administrators, fearing the chancellor's intent, set aside laws and ordinances, each making private teachings and striving to outdo one another, watering down purity and scattering simplicity, all practicing false appearances with name but no substance, growing lax and negligent, and in extreme cases becoming demonic." },
  { zh: "假令京師先行讓畔、異路、道不拾遺，其實亡益廉貪、貞淫之行，而以偽先天下，固未可也。", literal: "Suppose the capital region first practiced yielding boundaries, separate roads, and not picking up lost things on the road—in truth it would not benefit honest and greedy conduct or chaste and licentious behavior, yet with falsity leading all under Heaven, it truly could not be approved.", idiomatic: "Suppose the capital region first practiced yielding boundaries, separate roads, and not picking up lost things—in truth it would not improve honest or greedy conduct or chaste or licentious behavior, yet with falsity leading the empire, that truly could not be approved." },
  { zh: "即諸侯先行之，偽聲軼於京師，非細事也。", literal: "If the feudal lords practiced it first, false reputation would outrun the capital region—not a small matter.", idiomatic: "If the feudal lords practiced it first, false reputation would outrun the capital—not a small matter." },
  { zh: "漢家承敝通變，造起律令，所以勸善禁奸，條貫詳備，不可復加。", literal: "The House of Han inherited decline and adapted through change, creating laws and ordinances to encourage good and forbid wickedness—articles thorough and complete, not to be added to again.", idiomatic: "The House of Han inherited decline and adapted through change, creating laws and ordinances to encourage good and forbid wickedness—provisions thorough and complete, not to be added to again." },
  { zh: "宜令貴臣明飭長史、守丞，歸告二千石，舉三老、孝弟、力田、孝廉、廉吏，務得其人，郡事皆以法令為檢式，毋得擅為條教；", literal: "One ought to order noble ministers clearly to instruct chief clerks and administrators, return and tell the two-thousand-shi officials, present the three elders, filial and brotherly, strength-in-farming, filial and incorrupt, and honest officials, striving to obtain the right men; commandery affairs should all take laws and ordinances as models and measures, and none may on their own authority make regulations and teachings;", idiomatic: "Noble ministers ought clearly to instruct chief clerks and administrators to tell the two-thousand-shi officials to present the three elders, filial and brotherly men, strength-in-farming men, filial and incorrupt candidates, and honest officials, striving to obtain the right men; commandery affairs should all take laws and ordinances as the standard, and none may on their own authority make regulations and teachings;" },
  { zh: "敢挾詐偽以干名譽者，必先受戮，以正明好惡。", literal: "whoever dares to rely on fraud and falsity to seek fame and reputation should first receive punishment, to rectify and clarify likes and dislikes.", idiomatic: "whoever dares to rely on fraud and falsity to seek fame and reputation should first be punished, to rectify likes and dislikes." },
  { zh: "」天子嘉納敞言，召上計吏，使侍中臨飭，如敞指意。", literal: "\" The Son of Heaven praised and accepted Chang's words, summoned the annual-report clerks, and had a palace attendant oversee and instruct them according to Chang's intent.", idiomatic: "\" The emperor praised and accepted Chang's words, summoned the annual-report clerks, and had a palace attendant oversee and instruct them according to Chang's intent." },
  { zh: "霸甚慚。", literal: "Ba was deeply ashamed.", idiomatic: "Ba was deeply ashamed." },
  { zh: "又，樂陵侯史高以外屬民侍中，貴重，霸薦高可太尉。", literal: "Also, Marquis of Leling Shi Gao, a maternal relative by the female line serving as palace attendant, was honored and weighty; Ba recommended Gao for Grand Marshal.", idiomatic: "Also, Marquis of Leling Shi Gao, a maternal relative serving as palace attendant, was honored and influential; Ba recommended Gao for Grand Marshal." },
  { zh: "天子使尚書召問霸：「太尉官罷久矣。", literal: "The Son of Heaven had the Master of Documents summon and question Ba: \"The office of Grand Marshal has long been abolished.", idiomatic: "The emperor had the Master of Documents summon and question Ba: \"The office of Grand Marshal has long been abolished." },
  { zh: "夫宣明教化，通達幽隱，使獄無冤刑，邑無盜賊，君之職也。", literal: "To proclaim and clarify transformation and teaching, penetrate and reach the hidden and obscure, make prisons without wrongful punishment, and towns without bandits and thieves—that is the lord's duty.", idiomatic: "To proclaim and clarify teaching, reach the hidden and obscure, keep prisons free of wrongful punishment, and towns free of bandits and thieves—that is your duty." },
  { zh: "將相之官，朕之任焉。", literal: "The offices of general and minister—those are Our charge.", idiomatic: "The offices of general and minister are Our charge." },
  { zh: "侍中、樂陵侯高，帷幄近臣，朕之所自親，君何越職而舉之？", literal: "Palace Attendant, Marquis of Leling Gao, a close minister within the curtains—one We personally favor—why did you overstep your office and recommend him?", idiomatic: "Palace Attendant, Marquis of Leling Gao, a close minister within the curtains whom We personally favor—why did you overstep your office and recommend him?" },
  { zh: "」尚書令受丞相對，霸免冠謝罪，數日，乃決。", literal: "\" The Master of Documents received the chancellor's reply; Ba removed his cap and apologized for his crime; after several days it was settled.", idiomatic: "\" The Master of Documents received the chancellor's reply; Ba removed his cap and apologized; after several days the matter was settled." },
  { zh: "自是後不敢復有所請。", literal: "From this time forward he did not dare again to make any request.", idiomatic: "From then on he did not dare make any further request." },
  { zh: "然自漢興，言治民吏，以霸為首。", literal: "Yet since Han arose, in speaking of officials who govern the people, Ba is placed first.", idiomatic: "Yet since Han arose, in speaking of officials who govern the people, Ba ranks first." },
  { zh: "----3三月，上幸河東，祠-{后土}-。", literal: "----3 Third month: the emperor favored Hedong and sacrificed to -{后土}-.", idiomatic: "----3 In the third month the emperor traveled to Hedong and sacrificed to -{后土}-." },
  { zh: "減天下口錢；", literal: "He reduced the head-tax money throughout the empire;", idiomatic: "He reduced the head-tax money throughout the empire;" },
  { zh: "赦天下殊死以下。", literal: "he pardoned throughout the empire those below capital punishment.", idiomatic: "he pardoned throughout the empire those below capital punishment." },
  { zh: "----4六月，辛酉，以西河太守杜延年為御史大夫。", literal: "----4 Sixth month, day xinyou: he appointed Governor of Xihe Du Yannian as Censor-in-Chief.", idiomatic: "----4 In the sixth month, on day xinyou, he appointed Governor of Xihe Du Yannian Censor-in-Chief." },
  { zh: "----5置西河、北地屬國以處匈奴降者。", literal: "----5 He established dependent states in Xihe and Beidi to settle surrendered Xiongnu.", idiomatic: "----5 He established dependent states in Xihe and Beidi to settle surrendered Xiongnu." },
  { zh: "----6廣陵厲王胥使巫李女須祝詛上，求為天子。", literal: "----6 Prince Li Xu of Guangling had the witch Li Nüxu curse and imprecate the emperor, seeking to become Son of Heaven.", idiomatic: "----6 Prince Li Xu of Guangling had the witch Li Nüxu curse the emperor, seeking to become Son of Heaven." },
  { zh: "事覺，藥殺巫及宮人二十餘人以絕口。", literal: "When the matter was discovered, he poisoned the witch and more than twenty palace women to cut off testimony.", idiomatic: "When the matter was discovered, he poisoned the witch and more than twenty palace women to silence witnesses." },
  { zh: "公卿請誅胥。", literal: "Ministers and grandees requested executing Xu.", idiomatic: "Ministers and grandees requested executing Xu." },
  { zh: "1春，胥自殺。", literal: "1. Spring: Xu killed himself.", idiomatic: "1. In spring Xu killed himself." },
  { zh: "----2匈奴單于稱臣，遣弟右谷蠡王入侍。", literal: "----2 The Xiongnu Chanyu declared himself a subject and sent his younger brother, the Right Guli King, to attend court.", idiomatic: "----2 The Xiongnu Chanyu declared himself a subject and sent his younger brother, the Right Guli King, to attend court." },
  { zh: "以邊塞亡寇，減戍卒什二。", literal: "Because the border passes had no bandits, he reduced garrison soldiers by two-tenths.", idiomatic: "Because the border had no raiders, he reduced garrison soldiers by two-tenths." },
  { zh: "----3大司農中丞耿壽昌奏言：「歲數豐穰，谷賤，農人少利。", literal: "----3 Supervisor of the Grand Minister of Agriculture Geng Shouchang memorialized, saying: \"Years have been repeatedly abundant; grain is cheap and farmers gain little profit.", idiomatic: "----3 Supervisor of the Grand Minister of Agriculture Geng Shouchang memorialized, \"Years have been repeatedly abundant; grain is cheap and farmers gain little profit." },
  { zh: "故事：歲漕關東谷四百萬斛以給京師，用卒六萬人。", literal: "By precedent: each year four million hu of grain from east of the Pass were transported to supply the capital, using sixty thousand soldiers.", idiomatic: "By precedent each year four million hu of grain from east of the Pass were transported to supply the capital, using sixty thousand soldiers." },
  { zh: "宜糴三輔、弘農、河東、上黨、太原郡谷，足供京師，可以省關東漕卒過半。", literal: "One ought to buy grain from the Three Adjuncts, Hongnong, Hedong, Shangdang, and Taiyuan commanderies sufficient to supply the capital—this can save more than half the transport soldiers from east of the Pass.", idiomatic: "Grain should be bought from the Three Adjuncts, Hongnong, Hedong, Shangdang, and Taiyuan commanderies sufficient to supply the capital, saving more than half the transport soldiers from east of the Pass." },
  { zh: "」上從其計。", literal: "\" The emperor followed his plan.", idiomatic: "\" The emperor followed his plan." },
  { zh: "壽昌又白：「令邊郡皆築倉，以谷賤增其賈而糴，以利農，谷貴時減賈而糶，名曰常平倉。", literal: "Shouchang further reported: \"Order all frontier commanderies to build granaries; when grain is cheap, raise the price and buy in to benefit farmers; when grain is dear, lower the price and sell out—called Ever-Normal Granaries.", idiomatic: "Shouchang further reported, \"Order all frontier commanderies to build granaries; when grain is cheap, raise the price and buy in to benefit farmers; when grain is dear, lower the price and sell out—called Ever-Normal Granaries." },
  { zh: "」民便之。", literal: "\" The people found it convenient.", idiomatic: "\" The people found it convenient." },
  { zh: "上乃下詔賜壽昌爵關內侯。", literal: "The emperor thereupon issued an edict bestowing on Shouchang the rank Marquis within the Passes.", idiomatic: "The emperor thereupon decreed Shouchang the rank of Marquis within the Passes." },
  { zh: "----4夏，四月，辛丑朔，日有食之。", literal: "----4 Summer, fourth month, first day of the month xinchou: there was a solar eclipse.", idiomatic: "----4 In summer, the fourth month, on the first day xinchou, there was a solar eclipse." },
  { zh: "----5楊惲既失爵位，家居治產業，以財自娛。", literal: "----5 Yang Yun, having lost his noble rank, dwelt at home managing property and amused himself with wealth.", idiomatic: "----5 Yang Yun, having lost his noble rank, lived at home managing property and amused himself with wealth." },
  { zh: "其友人安定太守西河孫會宗與惲書，諫戒之，為言「大臣廢退，當闔門惶懼，為可憐之意；", literal: "His friend Sun Huizong, Governor of Anding of Xihe, wrote Yun a letter admonishing and warning him, saying \"When a great minister is dismissed and retired, he ought to shut his gates in fear and dread and show a pitiable attitude;", idiomatic: "His friend Sun Huizong, Governor of Anding of Xihe, wrote Yun a letter admonishing him, saying, \"When a great minister is dismissed and retired, he ought to shut his gates in fear and dread and show a pitiable attitude;" },
  { zh: "不當治產業，通賓客，有稱譽。", literal: "he ought not manage property, receive guests widely, and have praise and reputation.", idiomatic: "he ought not manage property, receive guests widely, and win praise and reputation." },
  { zh: "」惲，宰相子，有材能，少顯朝廷，一朝以晻昧語言見廢，內懷不服，報會宗書曰：「竊自思念，過已大矣，行已虧矣，常為農夫以沒世矣，是故身率妻子，戮力耕桑，不意當復用此為譏議也！", literal: "\" Yun, a chancellor's son with talent and ability, had early shown himself at court; in one morning he was dismissed on obscure words and inwardly harbored resentment. He replied to Huizong's letter, saying: \"Your servant privately reflects: my fault is already great, my conduct already impaired—I should always be a farmer to end my days; therefore I personally lead wife and children and exert strength in farming and sericulture, not expecting this would again be used as material for ridicule!", idiomatic: "\" Yun, a chancellor's son with talent and ability, had early distinguished himself at court; in one morning he was dismissed on obscure words and inwardly resented it. He replied to Huizong, \"Your servant reflects privately: my fault is already great and my conduct already impaired—I should be a farmer to the end of my days; therefore I personally lead wife and children and work at farming and sericulture, not expecting this would again be grounds for ridicule!" },
  { zh: "夫人情所不能止者，聖人弗禁，故君、父至尊、親，送其終也，有時而既。", literal: "What human feeling cannot be stopped, even sages do not forbid; therefore for ruler and father, most honored and most kin, when sending them to their end, there is a time and then it is done.", idiomatic: "What human feeling cannot be stopped, even sages do not forbid; therefore for ruler and father, most honored and most kin, when sending them to their end, there is a time and then it is done." },
  { zh: "臣之得罪，已三年矣，田家作苦，歲時伏臘，烹羊，炰羔，-{斗}-酒自勞，酒後耳熱，仰天拊缶呼烏烏，其詩曰：『田彼南山，蕪穢不治；", literal: "Your servant's offense is already three years; farm work is bitter; at seasonal times of Fuxi and Laji I boil sheep, roast lamb, a -{斗}- of wine to comfort myself; after wine my ears grow hot, I look up to heaven, strike the jar, and call out oowoo—its poem says: 'I farm that southern mountain, overgrown and uncultivated;", idiomatic: "Your servant's offense is already three years old; farm work is bitter; at the seasonal festivals of Fuxi and Laji I boil sheep, roast lamb, and with a -{斗}- of wine comfort myself; after wine my ears grow hot, I look up to heaven, strike the jar, and call out oowoo—its poem says, 'I farm that southern mountain, overgrown and uncultivated;" },
  { zh: "種一頃豆，落而為萁。", literal: "I plant a qing of beans—they fall and become beanstalks.", idiomatic: "I plant a qing of beans—they fall and become beanstalks." },
  { zh: "人生行樂耳，須富貴何時？", literal: "Human life is just doing pleasure—when must one wait for wealth and honor?", idiomatic: "Human life is just doing pleasure—when must one wait for wealth and honor?" },
  { zh: "』誠淫荒無度，不知其不可也。", literal: "' Truly licentious, wasteful, and without measure—he does not know it cannot be done.", idiomatic: "' Truly licentious, wasteful, and without measure—he does not know it cannot be done." },
  { zh: "」又惲兄子安平侯譚謂惲曰：「侯罪薄，又有功，且復用！", literal: "\" Also Yun's elder brother's son, Marquis of Anping Tan, said to Yun: \"The marquis's crime is slight and he also has merit—he will yet be employed again!", idiomatic: "\" Also Yun's elder brother's son, Marquis of Anping Tan, said to Yun, \"Your crime is slight and you also have merit—you will yet be employed again!" },
  { zh: "」惲曰：「有功何益！", literal: "\" Yun said: \"What good is merit!", idiomatic: "\" Yun said, \"What good is merit!" },
  { zh: "縣官不足為盡力。", literal: "The court is not worth exerting full effort for.", idiomatic: "The court is not worth exerting full effort for." },
  { zh: "」譚曰：「縣官實然。", literal: "\" Tan said: \"The court indeed is so.", idiomatic: "\" Tan said, \"The court indeed is so." },
  { zh: "蓋司隸、韓馮翊皆盡力吏也，俱坐事誅。", literal: "Former Director of the Metropolitan Area and Governor of Han, Fengyi, were both officials who exerted full effort—both sat in cases and were executed.", idiomatic: "Former Director of the Metropolitan Area and Governor of Han, Fengyi, were both officials who exerted full effort—both were executed for their cases." },
  { zh: "」會有日食之變，騶馬猥佐成上書告「惲驕奢，不悔過。", literal: "\" There happened to be the omen of a solar eclipse; Groom Wang Cheng submitted a memorial reporting \"Yun is arrogant and extravagant and does not repent his offense.", idiomatic: "\" There happened to be the omen of a solar eclipse; Groom Wang Cheng submitted a memorial reporting, \"Yun is arrogant and extravagant and does not repent." },
  { zh: "日食之咎，此人所致。", literal: "The blame for the solar eclipse—this man caused it.", idiomatic: "The blame for the solar eclipse—this man caused it." },
  { zh: "」章下廷尉，按驗，得所予會宗書，帝見而惡之。", literal: "\" The memorial was sent down to the Minister of Justice; on investigation they obtained the letter he had given Huizong; the emperor saw it and hated it.", idiomatic: "\" The memorial was sent to the Minister of Justice; on investigation they obtained the letter he had given Huizong; the emperor saw it and hated it." },
  { zh: "廷尉當惲大逆無道，要斬；", literal: "The Minister of Justice judged Yun guilty of great impiety and sentenced him to waist severing;", idiomatic: "The Minister of Justice judged Yun guilty of great impiety and sentenced him to execution at the waist;" },
  { zh: "妻子徙酒泉郡；", literal: "his wife and children were banished to Jiuquan commandery;", idiomatic: "his wife and children were banished to Jiuquan commandery;" },
  { zh: "譚坐免為庶人，諸在位與惲厚善者，未央衛尉韋玄成及孫會宗等，皆免官。", literal: "Tan sat in the case and was dismissed as a commoner; all in office who were thick friends with Yun—Weixuan of the Weiyang Guard of the Palace, Sun Huizong, and others—were all dismissed from office.", idiomatic: "Tan was dismissed as a commoner; all in office who were close friends of Yun—Weixuan, Guard of the Palace for Weiyang, Sun Huizong, and others—were all dismissed from office." },
  { zh: ":臣光曰：以孝宣之明，魏相、丙吉為丞相，-{于定國}-為廷尉，而趙、蓋、韓、楊之死皆不厭眾心，惜哉，其為善政之累大矣！", literal: ": Your servant Guang says: With Emperor Xiao Xuan's clarity, Wei Xiang and Bing Ji as chancellors, and -{于定國}- as Minister of Justice, yet the deaths of Zhao, Gai, Han, and Yang all failed to satisfy the people's hearts—alas, how great the burden on good government!", idiomatic: ": Your servant Guang says: With Emperor Xuan's clarity, Wei Xiang and Bing Ji as chancellors, and -{于定國}- as Minister of Justice, yet the deaths of Zhao, Gai, Han, and Yang all failed to satisfy popular sentiment—alas, how great the burden on good government!" },
  { zh: "《周官》司寇之法，有議賢、議能。", literal: "In the Zhou Offices, the Minister of Crime's law has deliberation for the worthy and deliberation for the capable.", idiomatic: "In the Zhou Offices, the Minister of Crime's law provides deliberation for the worthy and deliberation for the capable." },
  { zh: "若廣漢、延壽之治民，可不謂能乎！", literal: "If Guanghan and Yanshou's governing of the people—can they not be called capable!", idiomatic: "If Guanghan and Yanshou's governing of the people—can they not be called capable!" },
  { zh: "寬饒、惲之剛直，可不謂賢乎！", literal: "Kuanrao and Yun's firm uprightness—can they not be called worthy!", idiomatic: "Kuanrao and Yun's firm uprightness—can they not be called worthy!" },
  { zh: "然則雖有死罪，猶將宥之，況罪不足以死乎！", literal: "If so, though there were a death offense, one would still pardon them—how much more when the offense was not enough to die!", idiomatic: "If so, though there were a death offense, one would still pardon them—how much more when the offense did not warrant death!" },
  { zh: "揚子以韓馮翊之愬蕭為臣之自失。", literal: "Master Yang held that Governor of Han, Fengyi's suing Xiao was a minister's losing himself.", idiomatic: "Master Yang held that Governor of Han, Fengyi's suing Xiao was a minister losing himself." },
  { zh: "夫所以使延壽犯上者，望之激之也。", literal: "What made Yanshou offend his superior was Wang Zhi's provoking him.", idiomatic: "What made Yanshou offend his superior was Wang Zhi provoking him." },
  { zh: "上不之察，而延壽獨蒙其辜，不亦甚哉！", literal: "The emperor did not examine it, yet Yanshou alone bore the guilt—is it not extreme!", idiomatic: "The emperor did not examine it, yet Yanshou alone bore the guilt—is it not extreme!" },
  { zh: "----6匈奴閏振單于率其眾東擊郅支單于。", literal: "----6 Chanyu Runzhen of the Xiongnu led his masses east to attack Chanyu Zhizhi.", idiomatic: "----6 Chanyu Runzhen of the Xiongnu led his forces east to attack Chanyu Zhizhi." },
  { zh: "郅支與戰，殺之，併其兵；", literal: "Zhizhi fought with him, killed him, and merged his troops;", idiomatic: "Zhizhi fought him, killed him, and absorbed his troops;" },
  { zh: "遂進攻呼韓邪。", literal: "thereupon he advanced to attack Huhanye.", idiomatic: "then he advanced to attack Huhanye." },
  { zh: "呼韓邪兵敗走，郅支都單于庭。", literal: "Huhanye's army was defeated and fled; Zhizhi occupied the Chanyu's court.", idiomatic: "Huhanye was defeated and fled; Zhizhi occupied the Chanyu's court." },
  { zh: "1春，正月，行幸甘泉，郊泰畤。", literal: "1 In spring, the first month, the emperor traveled in favor to Sweet Springs and sacrificed at the Great Altar.", idiomatic: "1 In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "----2楊惲之誅也，公卿奏京兆尹張敞，惲之黨友，不宜處位。", literal: "----2 At Yang Yun's execution, the excellencies and ministers memorialized Metropolitan Governor Zhang Chang, Yun's partisan friend, as unfit to hold office.", idiomatic: "----2 At Yang Yun's execution, the excellencies and ministers memorialized Metropolitan Governor Zhang Chang, Yun's partisan friend, as unfit to hold office." },
  { zh: "上惜敞材，獨寢其奏，不下。", literal: "The emperor cherished Chang's talent and alone shelved their memorial, not sending it down.", idiomatic: "The emperor valued Chang's talent and alone shelved their memorial without acting on it." },
  { zh: "敞使掾絮舜有所案驗，舜私歸其家曰：「五日京兆耳，安能復案事！", literal: "Chang sent his clerk Xushun on some case to investigate; Xushun privately returned home and said: \"A five-day Metropolitan Governor—how can he again handle cases!", idiomatic: "Chang sent his clerk Xushun to investigate a case; Xushun went home privately and said, \"A five-day Metropolitan Governor—how can he handle cases again!" },
  { zh: "」敞聞舜語，即部吏收舜繫獄，晝夜驗治，竟致其死事。", literal: "\" Hearing Xushun's words, Chang immediately ordered officials to seize Xushun and imprison him; day and night he examined and prosecuted him, in the end bringing about his death in the case.", idiomatic: "\" Hearing this, Chang immediately had officials seize Xushun and imprison him; day and night he prosecuted the case until Xushun died in custody." },
  { zh: "舜當出死，敞使主簿持教告舜曰：「五日京兆竟何如？", literal: "When Xushun was about to go out to execution, Chang had his chief clerk hold the order and tell Xushun: \"How about that five-day Metropolitan Governor after all?", idiomatic: "When Xushun was about to be executed, Chang had his chief clerk bring the order and tell him, \"How about that five-day Metropolitan Governor after all?" },
  { zh: "冬月已盡，延命乎？", literal: "The winter month is already spent—extending your life, is it?", idiomatic: "Winter is nearly over—still extending your life, is it?" },
  { zh: "」乃棄舜市。", literal: "\" Thereupon he abandoned Xushun at the market.", idiomatic: "\" Then he had Xushun executed in the marketplace." },
  { zh: "會立春，行冤獄使者出，舜家載屍並編敞教，自言使者。", literal: "It happened to be the Establishment of Spring; the envoy reviewing wrongful imprisonment cases went forth; Xushun's family loaded the corpse together with a copy of Chang's order and themselves told the envoy.", idiomatic: "It happened to be the Establishment of Spring, when envoys reviewing wrongful imprisonment went forth; Xushun's family brought the corpse together with a copy of Chang's order and appealed to the envoy." },
  { zh: "使者奏敞賊殺不辜。", literal: "The envoy memorialized that Chang had murdered the innocent as a bandit.", idiomatic: "The envoy memorialized that Chang had murdered an innocent man." },
  { zh: "上欲令敞得自便，即先下敞前坐楊惲奏，免為庶人。", literal: "The emperor wished to let Chang obtain convenience for himself and first sent down Chang's earlier conviction in the Yang Yun case, dismissing him as a commoner.", idiomatic: "The emperor wished to let Chang go free and first sent down his earlier conviction in the Yang Yun case, dismissing him as a commoner." },
  { zh: "敞詣闕上印綬，便從闕下亡命。", literal: "Chang went to the palace gate and returned his seal and cord, then straightway fled for his life from below the gate.", idiomatic: "Chang went to the palace gate, returned his seal and cord, and fled for his life from below the gate." },
  { zh: "數月，京師吏民解馳，枹鼓數起，而翼州部中有大賊，天子思敞功效，使使者即家在所召敞。", literal: "Several months later, the capital's officials and people grew slack; drum-beats of alarm repeatedly arose; and in the Jizhou region there was a great bandit—the Son of Heaven thought of Chang's achievements and sent an envoy to summon Chang at his home where he was.", idiomatic: "Several months later, law and order in the capital slackened and alarms repeatedly sounded; meanwhile a great bandit arose in the Jizhou region. The emperor recalled Chang's achievements and sent an envoy to summon him at his home." },
  { zh: "敞身被重劾，及使者至，妻子家室皆泣，惶懼，而敞獨笑曰：「吾身亡命為民，郡吏當就捕。", literal: "Chang's person bore heavy impeachments; when the envoy arrived, wife, children, and household all wept in fear and dread, yet Chang alone laughed and said: \"I fled for my life on behalf of the people; the commandery officials ought to come and arrest me.", idiomatic: "Chang faced serious charges; when the envoy arrived, his wife, children, and household all wept in fear, yet Chang alone laughed and said, \"I fled for the people's sake; the commandery officials ought to come and arrest me." },
  { zh: "今使者來，此天子欲用我也。", literal: "Now the envoy has come—this means the Son of Heaven wishes to employ me.", idiomatic: "Now the envoy has come—this means the emperor wishes to employ me." },
  { zh: "」裝隨使者，詣公車上書曰：「臣前幸得備位列卿，待罪京兆，坐殺掾絮舜。", literal: "\" He packed and followed the envoy, went to the Imperial Carriages Office and submitted a memorial, saying: \"Your subject before was fortunate to be ranked among the ministers, held office in guilt at the capital metropolis, and sat in judgment for killing clerk Xushun.", idiomatic: "\" He packed and followed the envoy, went to the Imperial Carriages Office and submitted a memorial: \"Your subject was once fortunate to rank among the ministers and served as Metropolitan Governor, where I was convicted of killing clerk Xushun." },
  { zh: "舜本臣敞素所厚吏，數蒙恩貸。", literal: "Xushun was originally an official your subject Chang had long favored, repeatedly receiving grace and leniency.", idiomatic: "Xushun was an official I had long favored and repeatedly spared." },
  { zh: "以臣有章劾當免，受記考事，便歸臥家，謂臣『五日京兆』。", literal: "Because your subject had an impeachment memorial and ought to be dismissed, he received a note to examine the case and straightway returned to lie at home, calling your subject 'a five-day Metropolitan Governor.'", idiomatic: "When I faced impeachment and ought to be dismissed, he received orders to investigate a case, went straight home, and called me 'a five-day Metropolitan Governor.'" },
  { zh: "背恩忘義，傷薄欲化。", literal: "He turned his back on grace and forgot righteousness, injuring shallow desires for transformation.", idiomatic: "He turned his back on grace and forgot righteousness, undermining my efforts at reform." },
  { zh: "臣竊以舜無狀，枉法以誅之。", literal: "Your subject privately held that Xushun was without proper form and bent the law to execute him.", idiomatic: "Your subject held that Xushun was insolent and executed him by bending the law." },
  { zh: "臣敞賊殺不辜，鞠獄故不直，雖伏明法，死無所恨！", literal: "Your subject Chang, murdering the innocent as a bandit, bent the prison examination and therefore was not upright—though he submits to the clear law, in death he has no regret!", idiomatic: "Your subject Chang murdered an innocent man and conducted the trial unjustly—though I submit to the clear law, I die without regret!" },
  { zh: "」天子引見敞，拜為冀州刺史。", literal: "\" The Son of Heaven summoned Chang to audience and appointed him Inspector of Jizhou.", idiomatic: "\" The emperor received Chang in audience and appointed him Inspector of Jizhou." },
  { zh: "敞到部，盜賊屏跡。", literal: "When Chang reached his inspectorate, bandits vanished from sight.", idiomatic: "When Chang reached his post, bandits vanished." },
  { zh: "----3皇太子柔仁好儒，見上所用多文法吏，以刑繩下，嘗侍燕從容言：「陛下持刑太深，宜用儒生。", literal: "----3 The heir apparent was gentle, benevolent, and fond of Confucianism; seeing that those the emperor employed were mostly legalist officials who bound the people with punishments, he once while attending a banquet spoke at ease: \"Your Majesty holds punishments too deep; you ought to employ Confucian scholars.", idiomatic: "----3 The heir apparent was gentle, benevolent, and fond of Confucianism; seeing that the emperor employed mostly legalist officials who governed by punishments, he once at a banquet said at ease, \"Your Majesty applies punishments too harshly; you ought to employ Confucian scholars." },
  { zh: "」帝作色曰：「漢家自有制度，本以霸王道雜之。", literal: "\" The emperor changed countenance and said: \"The House of Han has its own institutions, fundamentally mixing the ways of hegemon and king.", idiomatic: "\" The emperor's expression changed and he said, \"The House of Han has its own institutions, fundamentally mixing the ways of hegemon and king." },
  { zh: "奈何純任德教，用周政乎！", literal: "How can one purely entrust moral teaching and employ Zhou government!", idiomatic: "How can one rely purely on moral teaching and employ Zhou government!" },
  { zh: "且俗儒不達時宜，好是古非今，使人眩於名實，不知所守，何足委任！", literal: "Moreover vulgar Confucians do not comprehend the timely fit, delight in praising antiquity and condemning the present, and make people dazzled between name and reality, not knowing what to uphold—how are they fit to be entrusted!", idiomatic: "Moreover vulgar Confucians do not grasp the times, delight in praising antiquity and condemning the present, and dazzle people between name and reality so they do not know what to uphold—how can they be entrusted!" },
  { zh: "」乃歎曰：「亂我家者，太子也！", literal: "\" He then sighed and said: \"He who will disorder my house is the heir apparent!", idiomatic: "\" He then sighed and said, \"He who will disorder my house is the heir apparent!" },
  { zh: ":臣光曰：王霸無異道。", literal: ": Minister Guang said: The ways of king and hegemon are not different paths.", idiomatic: ": Minister Guang said: The ways of king and hegemon are not different paths." },
  { zh: "昔三代之隆，禮樂、征伐自天子出，則謂之王。", literal: "In antiquity at the height of the Three Dynasties, when rites and music and campaigns and punishments issued from the Son of Heaven, it was called kingship.", idiomatic: "In antiquity at the height of the Three Dynasties, when rites, music, and campaigns issued from the Son of Heaven, it was called kingship." },
  { zh: "天子微弱不能治諸侯，諸侯有能率其與國同討不庭以尊王室者，則謂之霸。", literal: "When the Son of Heaven was weak and could not govern the feudal lords, and a feudal lord was able to lead the states allied with him jointly to punish the disobedient and honor the royal house, it was called hegemony.", idiomatic: "When the Son of Heaven was weak and could not govern the feudal lords, and a lord was able to lead allied states to punish the disobedient and honor the royal house, it was called hegemony." },
  { zh: "其所以行之也，皆本仁祖義，任賢使能，賞善罰惡，禁暴誅亂。", literal: "The means by which they were carried out all took benevolence as root and righteousness as model, employed the worthy and used the able, rewarded good and punished evil, forbade violence and executed disorder.", idiomatic: "The means by which both were carried out all took benevolence as root and righteousness as model, employed the worthy, rewarded good and punished evil, and forbade violence." },
  { zh: "顧名位有尊卑，德澤有深淺，功業有鉅細，政令有廣狹耳，非若白黑、甘苦之相反也。", literal: "Only that name and position had high and low, virtue's favor had deep and shallow, achievements had large and small, and government orders had broad and narrow—that is all; it is not like black and white or sweet and bitter in mutual opposition.", idiomatic: "Only that rank had high and low, favor had depth, achievements had scale, and orders had scope—that is all; it is not like black and white or sweet and bitter in opposition." },
  { zh: "漢之所以不能復三代之治者，由人主之不為，非先王之道不可復行於後世也。", literal: "The reason Han could not restore the governance of the Three Dynasties was that the human ruler did not do it—not that the former kings' Way could not again be practiced in later generations.", idiomatic: "The reason Han could not restore Three Dynasties governance was that rulers did not do it—not that the former kings' Way could not be practiced again." },
  { zh: "夫儒有君子，有小人。", literal: "Among Confucians there are gentlemen and there are petty men.", idiomatic: "Among Confucians there are gentlemen and petty men." },
  { zh: "彼俗儒者，誠不足與為治也，獨不可求真儒而用之乎？", literal: "Those vulgar Confucians truly are not fit to govern with—but can one alone not seek true Confucians and employ them?", idiomatic: "Those vulgar Confucians truly are not fit to govern with—but cannot one seek true Confucians and employ them?" },
  { zh: "稷、契、皋陶、伯益、伊尹、周公、孔子，皆大儒也，使漢得而用之，功烈豈若是而止邪！", literal: "Ji, Qi, Gao Yao, Bo Yi, Yi Yin, Duke of Zhou, and Confucius were all great Confucians; had Han obtained and employed them, would achievements and glory have stopped like this!", idiomatic: "Ji, Qi, Gao Yao, Bo Yi, Yi Yin, Duke of Zhou, and Confucius were all great Confucians; had Han obtained and employed them, would achievements have stopped at this!" },
  { zh: "孝宣謂太子懦而不立，闇於治體，必亂我家，則可矣；", literal: "Emperor Xuan's saying the heir apparent was weak and could not stand, dark to the body of governance, and would surely disorder his house—that could pass;", idiomatic: "Emperor Xuan's saying the heir apparent was weak, unfit to stand, ignorant of governance, and would disorder his house—that could pass;" },
  { zh: "乃曰王道不可行，儒者不可用，豈不過甚矣哉！", literal: "yet to say the kingly Way could not be practiced and Confucians could not be employed—was that not going too far!", idiomatic: "yet to say the kingly Way could not be practiced and Confucians could not be employed—was that not going too far!" },
  { zh: "殆非所以訓示子孫，垂法將來者也。", literal: "It was nearly not the means to instruct and show sons and grandsons or to hand down law for the future.", idiomatic: "It was hardly the way to instruct posterity or hand down law for the future." },
  { zh: "----4淮陽憲王好法律，聰達有材；", literal: "----4 Prince Xian of Huaiyang was fond of law, clever and penetrating with talent;", idiomatic: "----4 Prince Xian of Huaiyang was fond of law, clever and talented;" },
  { zh: "王母張婕妤尤幸。", literal: "his queen mother, Lady Zhang the Beautiful Companion, was especially favored.", idiomatic: "his queen mother, Lady Zhang the Beautiful Companion, was especially favored." },
  { zh: "上由是疏太子而愛淮陽憲王，數嗟歎憲王曰：「真我子也！", literal: "The emperor thereby grew distant from the heir apparent and loved Prince Xian of Huaiyang, repeatedly sighing in admiration of the prince and saying: \"Truly my son!", idiomatic: "The emperor thereby grew distant from the heir apparent and loved Prince Xian of Huaiyang, repeatedly sighing and saying, \"Truly my son!" },
  { zh: "」常有意欲立憲王，然用太子起於微細，上少依倚許氏，及即位而許后以殺死，故弗忍也。", literal: "\" He constantly had intent to establish Prince Xian, yet because the heir apparent had risen from minute origins and the emperor in youth had relied on the Xu clan, and after accession the Empress Xu died by killing, he therefore could not bear it.", idiomatic: "\" He constantly intended to establish Prince Xian, yet because the heir apparent had risen from humble origins, the emperor in youth had relied on the Xu clan, and after accession Empress Xu died by execution, he could not bear to do it." },
  { zh: "久之，上拜韋玄成為淮陽中尉，以玄成嘗讓爵于兄，欲以感諭憲王。", literal: "After a long time, the emperor appointed Wei Xuancheng as Commandant of Huaiyang, because Xuancheng had once yielded his noble rank to his elder brother, wishing thereby to move and instruct Prince Xian.", idiomatic: "After a long time, the emperor appointed Wei Xuancheng Commandant of Huaiyang, because Xuancheng had once yielded his noble rank to his elder brother, wishing thereby to instruct Prince Xian by example." },
  { zh: "由是太子遂安。", literal: "Thereby the heir apparent was at last secure.", idiomatic: "Thereby the heir apparent was at last secure." },
  { zh: "----5匈奴呼韓邪單于之敗也，左伊秩訾王為呼韓邪計，勸令稱臣入朝事漢，從漢求助，如此，匈奴乃定。", literal: "----5 When the Xiongnu Chanyu Huhanye was defeated, the Left Yizhi Zhi King made a plan for Huhanye, urging him to declare himself a subject, enter court, and serve Han, follow Han to seek aid—thus the Xiongnu would be settled.", idiomatic: "----5 When Chanyu Huhanye of the Xiongnu was defeated, the Left Yizhi Zhi King advised him to declare himself a subject, attend court, and serve Han, seeking Han's aid—thus the Xiongnu would be settled." },
  { zh: "呼韓邪問諸大臣，皆曰：「不可。", literal: "Huhanye asked the various great ministers; all said: \"It cannot be done.", idiomatic: "Huhanye asked the great ministers; all said, \"It cannot be done." },
  { zh: "匈奴之俗，本上氣力而下服役，以馬上戰鬥為國，故有威名於百蠻。", literal: "The Xiongnu custom esteems above physical strength and below servitude; taking battle on horseback as the state, therefore they have a prestigious name among the hundred barbarians.", idiomatic: "Xiongnu custom esteems strength above and servitude below; taking battle on horseback as the foundation of state, they have prestige among the hundred barbarians." },
  { zh: "戰死，壯士所有也。", literal: "To die in battle is what a stalwart man possesses.", idiomatic: "To die in battle is a stalwart man's portion." },
  { zh: "今兄弟爭國，不在兄則在弟，雖死猶有威名，子孫常長諸國。", literal: "Now brothers contend for the state—if not the elder brother then the younger; though one dies he still has a prestigious name, and sons and grandsons constantly lead the various states.", idiomatic: "Now brothers contend for the state—if not the elder then the younger; though one dies he still wins prestige, and sons and grandsons will long lead the various states." },
  { zh: "漢雖強，猶不能兼併匈奴。", literal: "Though Han is strong, it still cannot annex and merge the Xiongnu.", idiomatic: "Though Han is strong, it still cannot annex the Xiongnu." },
  { zh: "奈何亂先古之制，臣事於漢，卑辱先單于，為諸國所笑！", literal: "How can we disorder the institutions of former antiquity, serve Han as subjects, and humiliate the former Chanyu, becoming what the various states laugh at!", idiomatic: "How can we overturn ancient institutions, serve Han as subjects, humiliate the former Chanyu, and become a laughingstock to the various states!" },
  { zh: "雖如是而安，何以復長百蠻！", literal: "Even if we were secure thus, how could we again lead the hundred barbarians!", idiomatic: "Even if we were secure thus, how could we again lead the hundred barbarians!" },
  { zh: "」左伊秩訾曰：「不然，強弱有時。", literal: "\" The Left Yizhi Zhi said: \"It is not so—strength and weakness have their seasons.", idiomatic: "\" The Left Yizhi Zhi said, \"It is not so—strength and weakness have their seasons." },
  { zh: "今漢方盛，烏孫城郭諸國皆為臣妾。", literal: "Now Han is flourishing; the walled states of Wusun and all the rest have become subjects and concubines.", idiomatic: "Now Han is flourishing; the walled states of Wusun and all the rest have become Han subjects." },
  { zh: "自且鞮侯單于以來，匈奴日削，不能取復，雖屈強於此，未嘗一日安也。", literal: "From the time of Chanyu Qiedihou onward, the Xiongnu daily dwindled and could not recover; though they bent their strength here, they never had a single day of peace.", idiomatic: "Since Chanyu Qiedihou, the Xiongnu have daily dwindled and could not recover; though they bent their strength here, they never had a day of peace." },
  { zh: "今事漢則安存，不事則危亡，計何以過此！", literal: "Now to serve Han is security and survival; not to serve is peril and extinction—what plan surpasses this!", idiomatic: "Now to serve Han is security; not to serve is extinction—what plan surpasses this!" },
  { zh: "」諸大人相難久之，呼韓邪從其計，引眾南近塞，遣子右賢王銖婁渠堂入侍。", literal: "\" The various great men disputed one another for a long time; Huhanye followed his plan, led his masses south near the passes, and sent his son the Right Wise King Zhu Louqu Tang to enter and attend court.", idiomatic: "\" The great men disputed for a long time; Huhanye followed his plan, led his people south near the border, and sent his son the Right Wise King Zhu Louqu Tang to attend court." },
  { zh: "郅支單于亦遣子右大將駒于利受入侍。", literal: "Chanyu Zhizhi also sent his son the Right Grand General Juyu Lishou to enter and attend court.", idiomatic: "Chanyu Zhizhi also sent his son the Right Grand General Juyu Lishou to attend court." },
  { zh: "----6二月，丁巳，樂成敬侯許延壽薨。", literal: "----6 In the second month, on day dingsi, Marquis Jing of Lecheng Xu Yanshou died.", idiomatic: "----6 In the second month, on day dingsi, Marquis Jing of Lecheng Xu Yanshou died." },
  { zh: "----7夏，四月，黃龍見新豐。", literal: "----7 In summer, the fourth month, a yellow dragon appeared at Xinfeng.", idiomatic: "----7 In summer, the fourth month, a yellow dragon appeared at Xinfeng." },
  { zh: "----8丙申，太上皇廟火；", literal: "----8 On day bingshen, the Grand Supreme Emperor's temple caught fire;", idiomatic: "----8 On day bingshen, the Grand Supreme Emperor's temple caught fire;" },
  { zh: "甲辰，孝文廟火；", literal: "on day jiachen, Emperor Wen's temple caught fire;", idiomatic: "on day jiachen, Emperor Wen's temple caught fire;" },
  { zh: "上素服五日。", literal: "the emperor wore plain white garments for five days.", idiomatic: "the emperor wore plain mourning garments for five days." },
  { zh: "----9烏孫狂王復尚楚主解憂，生一男鴟靡，不與主和，又暴惡失眾。", literal: "----9 The Mad King of Wusun again took in marriage the Chu princess Jieyou and begot a son, Nimi; he was not harmonious with the princess and again was violent and wicked, losing the masses.", idiomatic: "----9 The Mad King of Wusun again married the Chu princess Jieyou and begot a son, Nimi; he was not harmonious with her and was violent and wicked, losing popular support." },
  { zh: "漢使衛司馬魏和意、副侯任昌至烏孫。", literal: "Han sent Guard Major Wei Heyi and Deputy Marquis Ren Chang to Wusun.", idiomatic: "Han sent Guard Major Wei Heyi and Deputy Marquis Ren Chang to Wusun." },
  { zh: "公主言：「狂王為烏孫所患苦，易誅也。", literal: "The princess said: \"The Mad King is what Wusun suffers from; he is easy to execute.", idiomatic: "The princess said, \"The Mad King is what Wusun suffers from; he is easy to kill." },
  { zh: "」遂謀置酒，使士拔劍擊之。", literal: "\" They thereupon plotted to set out wine and had soldiers draw swords and strike him.", idiomatic: "\" They plotted a banquet and had soldiers draw swords and strike him." },
  { zh: "劍旁下，狂王傷，上馬馳去。", literal: "The sword struck beside him; the Mad King was wounded, mounted his horse, and galloped away.", idiomatic: "The sword struck beside him; the Mad King was wounded, mounted his horse, and fled." },
  { zh: "其子細沈瘦會兵圍和意、昌及公主於赤谷城。", literal: "His son Xishen Sou gathered troops and besieged Heyi, Chang, and the princess at Red Valley City.", idiomatic: "His son Xishen Sou gathered troops and besieged Heyi, Chang, and the princess at Red Valley City." },
  { zh: "數月，都護鄭吉發諸國兵救之，乃解去。", literal: "Several months later, Protector-General Zheng Ji mobilized the various states' troops to rescue them, and the siege was then lifted.", idiomatic: "Several months later, Protector-General Zheng Ji mobilized troops from the various states to rescue them, and the siege was lifted." },
  { zh: "漢遣中郎將張遵持醫藥治狂王，賜金帛。", literal: "Han sent Palace Gentleman Zhang Zun bearing medicine to treat the Mad King and bestowed gold and silks.", idiomatic: "Han sent Palace Gentleman Zhang Zun with medicine to treat the Mad King and bestowed gold and silks." },
  { zh: "因收和意、昌系瑣，從尉犁檻車至長安，斬之。", literal: "Thereupon Heyi and Chang were seized in fetters, sent in a caged cart from Weili to Chang'an, and beheaded.", idiomatic: "Thereupon Heyi and Chang were seized in fetters, sent in a caged cart from Weili to Chang'an, and beheaded." },
  { zh: "初，肥王翁歸靡胡婦子烏就屠，狂王傷時，驚，與諸翎侯俱去，居北山中，揚言母家匈奴兵來，故眾歸之。", literal: "Earlier, the Fat King Wengguimi's son by a Hu woman was Wujiutu; when the Mad King was wounded, startled, he went off together with the various commandery lords and dwelt in the northern mountains, proclaiming that his mother's family, the Xiongnu, were coming with troops—therefore the masses turned to him.", idiomatic: "Earlier, the Fat King Wengguimi's son by a Hu woman was Wujiutu; when the Mad King was wounded, startled, he went off with the various commandery lords and dwelt in the northern mountains, proclaiming that Xiongnu troops from his mother's family were coming—therefore the people turned to him." },
  { zh: "後遂襲殺狂王，自立為昆彌。", literal: "Later he thereupon raided and killed the Mad King and established himself as Kunmi.", idiomatic: "Later he raided and killed the Mad King and established himself as Kunmi." },
  { zh: "是歲，漢遣破羌將軍辛武賢將兵萬五千人至敦煌，通渠積穀，欲以討之。", literal: "That year, Han sent Break-Qiang General Xin Wuxian to lead fifteen thousand troops to Dunhuang, open canals and store grain, intending thereby to campaign against him.", idiomatic: "That year, Han sent Break-Qiang General Xin Wuxian with fifteen thousand troops to Dunhuang to open canals and store grain, intending to campaign against him." },
  { zh: "初，楚主侍者馮嫽，能史書，習事，嘗持漢節為公主使，城郭諸國敬信之，號曰馮夫人，為烏孫右大將妻。", literal: "Earlier, the Chu princess's attendant Feng Liao could write histories and was practiced in affairs; she had once held Han credentials as the princess's envoy; the walled states all respected and trusted her and called her Lady Feng; she was wife to Wusun's Right Grand General.", idiomatic: "Earlier, the Chu princess's attendant Feng Liao could write and was skilled in affairs; she had held Han credentials as the princess's envoy; the walled states respected and trusted her and called her Lady Feng; she was wife to Wusun's Right Grand General." },
  { zh: "右大將與烏就屠相愛，都護鄭吉使馮夫人說烏就屠，以漢兵方出，必見滅，不如降。", literal: "The Right Grand General and Wujiutu were mutually fond; Protector-General Zheng Ji had Lady Feng persuade Wujiutu that Han troops were just going forth and he would surely be destroyed—better to surrender.", idiomatic: "The Right Grand General and Wujiutu were close; Protector-General Zheng Ji had Lady Feng persuade Wujiutu that Han troops were marching and he would surely be destroyed—better to surrender." },
  { zh: "烏就屠恐，曰：「願得小號以自處！", literal: "Wujiutu was afraid and said: \"I wish to obtain a lesser title by which to settle myself!", idiomatic: "Wujiutu was afraid and said, \"I wish to obtain a lesser title to maintain myself!" },
  { zh: "」帝征馮夫人，自問狀。", literal: "\" The emperor summoned Lady Feng and himself asked the circumstances.", idiomatic: "\" The emperor summoned Lady Feng and questioned her himself." },
  { zh: "遣謁者竺次、期門甘延壽為副，送馮夫人。", literal: "He dispatched Usher Zhu Ci and Palace Gate Guard Gan Yanshou as deputies to escort Lady Feng.", idiomatic: "He dispatched Usher Zhu Ci and Palace Gate Guard Gan Yanshou as deputies to escort Lady Feng." },
  { zh: "馮夫人錦車持節，詔烏就屠詣長羅侯赤谷城，立元貴靡為大昆彌，烏就屠為小昆彌，皆賜印綬。", literal: "Lady Feng in a brocade carriage held credentials and ordered Wujiutu to proceed to the Chief Luo Marquis at Red Valley City; Yuan Guimi was established as Great Kunmi, Wujiutu as Lesser Kunmi—both were bestowed seals and cords.", idiomatic: "Lady Feng in a brocade carriage held credentials and ordered Wujiutu to Red Valley City; Yuan Guimi was established as Great Kunmi, Wujiutu as Lesser Kunmi—both received seals and cords." },
  { zh: "破羌將軍不出塞，還。", literal: "The Break-Qiang General did not go beyond the passes and returned.", idiomatic: "The Break-Qiang General did not cross the border and returned." },
  { zh: "後烏就屠不盡歸諸翎侯民眾，漢復遣長羅侯將三校屯赤谷，因為分別其人民地界，大昆彌戶六萬餘，小昆彌戶四萬餘。", literal: "Later Wujiutu did not fully return the various commandery lords' people and masses; Han again sent the Chief Luo Marquis to lead three garrisons to encamp at Red Valley and thereby divide their people's territorial boundaries—Great Kunmi had more than sixty thousand households, Lesser Kunmi more than forty thousand.", idiomatic: "Later Wujiutu did not fully return the people's masses; Han again sent the Chief Luo Marquis with three garrisons to encamp at Red Valley and divide their territories—Great Kunmi had more than sixty thousand households, Lesser Kunmi more than forty thousand." },
  { zh: "然眾心皆附小昆彌。", literal: "Yet all hearts attached to the Lesser Kunmi.", idiomatic: "Yet popular support all attached to the Lesser Kunmi." },
  { zh: "1春，正月，立皇子囂為定陶王。", literal: "1 In spring, the first month, the emperor's son Biao was established as Prince of Dingtao.", idiomatic: "1 In spring, the first month, the emperor's son Biao was established as Prince of Dingtao." },
  { zh: "----2詔赦天下，減民算三十。", literal: "----2 An edict amnestied all under Heaven and reduced the people's poll tax by thirty.", idiomatic: "----2 An edict amnestied all under Heaven and reduced the poll tax by thirty." },
  { zh: "----3珠崖郡反。", literal: "----3 Zhuya Commandery rebelled.", idiomatic: "----3 Zhuya Commandery rebelled." },
  { zh: "夏，四月，遣護軍都尉張祿將兵擊之。", literal: "In summer, the fourth month, Colonel of the Guard Zhang Lu was dispatched to lead troops and strike them.", idiomatic: "In summer, the fourth month, Colonel of the Guard Zhang Lu was dispatched with troops to attack them." },
  { zh: "----4杜延年以老病免。", literal: "----4 Du Yannian was dismissed because of old age and illness.", idiomatic: "----4 Du Yannian was dismissed because of old age and illness." },
  { zh: "五月，己丑，廷尉-{于定國}-為御史大夫。", literal: "In the fifth month, on day jichou, Director of Justice Yu Dingguo became Censor-in-Chief.", idiomatic: "In the fifth month, on day jichou, Director of Justice Yu Dingguo became Censor-in-Chief." },
  { zh: "----5秋，九月，立皇子宇為東平王。", literal: "----5 In autumn, the ninth month, the emperor's son Yu was established as Prince of Dongping.", idiomatic: "----5 In autumn, the ninth month, the emperor's son Yu was established as Prince of Dongping." },
  { zh: "----6冬，十二月，上行幸萯陽宮、屬玉觀。", literal: "----6 In winter, the twelfth month, the emperor traveled in favor to Fuyang Palace and Jade-Quail View.", idiomatic: "----6 In winter, the twelfth month, the emperor traveled to Fuyang Palace and Jade-Quail View." },
  { zh: "----7是歲，營平壯武侯趙充國薨。", literal: "----7 That year, Marquis Zhuangwu of Yingping Zhao Chongguo died.", idiomatic: "----7 That year, Marquis Zhuangwu of Yingping Zhao Chongguo died." },
  { zh: "先是，充國以老乞骸骨，賜安車、駟馬、黃金，罷就第。", literal: "Earlier, Chongguo because of age requested his bones and was bestowed a secure carriage, four-horse team, and gold, dismissed to return to his estate.", idiomatic: "Earlier, Chongguo because of age requested retirement and was granted a secure carriage, four-horse team, and gold, then dismissed to his estate." },
  { zh: "朝廷每有四夷大議，常與參兵謀、問籌策焉。", literal: "Whenever the court had great deliberations on the four Yi, it constantly had him participate in military planning and ask his stratagems.", idiomatic: "Whenever the court had major deliberations on the four barbarians, it constantly consulted him on military planning and strategy." },
  { zh: "----8匈奴呼韓邪單于款五原塞，原奉國珍，朝三年正月。", literal: "----8 The Xiongnu Chanyu Huhanye came in good faith to Wuyuan Pass, wishing to present national treasures and attend court in the first month of the third year.", idiomatic: "----8 The Xiongnu chanyu Huhanye came in good faith to Wuyuan Pass, wishing to present national treasures and attend court in the first month of the third year." },
  { zh: "詔有司議其儀。", literal: "An edict ordered the relevant offices to deliberate on the ceremonial arrangements.", idiomatic: "An edict ordered the relevant offices to deliberate on the ceremonial arrangements." },
  { zh: "丞相、御史曰：「聖王之制，先京師而後諸夏，先諸夏而後夷狄。", literal: "The chancellor and censor-in-chief said: \"The sage king's system puts the capital first, then the various Xia; the various Xia first, then the Yi and Di.", idiomatic: "The chancellor and censor-in-chief said, \"The sage king's system puts the capital first, then the various Xia; the various Xia first, then the Yi and Di.\"" },
  { zh: "匈奴單于朝賀，其禮儀宜如諸侯王，位次在下。", literal: "When the Xiongnu chanyu comes to court for congratulations, his ceremonial observances should be like those of feudal kings, with his place in rank below them.", idiomatic: "When the Xiongnu chanyu comes to court for congratulations, his ceremonial observances should be like those of feudal kings, with his place in rank below them." },
  { zh: "」太子太傅蕭望之以為：「單于非正朔所加，故稱敵國，宜待以不臣之禮，位在諸侯王上。", literal: "\" The tutor of the heir apparent Xiao Wangzhi held: \"The chanyu is not one upon whom the correct calendar was conferred; he is therefore called a rival state. He should be received with the ritual due one who is not a subject, with rank above the feudal kings.", idiomatic: "\" Tutor of the Heir Apparent Xiao Wangzhi argued, \"The chanyu is not one upon whom the correct calendar was conferred; he is therefore called a rival state. He should be received with the ritual due one who is not a subject, with rank above the feudal kings.\"" },
  { zh: "外夷稽首稱籓，中國讓而不臣，此則羈縻之誼，謙亨之福也。", literal: "The outer Yi bow and call themselves vassals; the Central States yield and do not make them subjects—this is the meaning of bridling and tying, the fortune of humble attainment.", idiomatic: "The outer barbarians bow and call themselves vassals; the Central States yield and do not make them subjects—this is the meaning of keeping them on loose reins, the fortune of modest forbearance." },
  { zh: "《書》曰：『戎狄荒服，』言其來服荒忽亡常。", literal: "The Documents says: 'The Rong and Di are wild-domain tribute,' meaning that they come to submit in wildness, suddenly appearing and vanishing without constancy.", idiomatic: "The Book of Documents says, \"The Rong and Di are wild-domain tribute,\" meaning that they come to submit from distant lands, suddenly appearing and vanishing without constancy." },
  { zh: "如使匈奴後嗣卒有鳥竄鼠伏，闕於朝享，不為畔臣，萬世之長策也。", literal: "If the Xiongnu's later generations in the end scurry like birds and hide like rats, fail in court attendance, yet are not rebellious subjects—that is a long-range policy for ten thousand generations.", idiomatic: "If the Xiongnu's later generations in the end scurry like birds and hide like rats, fail in court attendance, yet are not treated as rebellious subjects—that is a long-range policy for ten thousand generations." },
  { zh: "」天子采之，下詔曰：「匈奴單于稱北蕃，朝正朔。", literal: "\" The Son of Heaven adopted this and issued an edict: \"The Xiongnu chanyu calls himself the northern藩 and attends the correct calendar.", idiomatic: "\" The emperor adopted this and issued an edict: \"The Xiongnu chanyu calls himself the northern藩 and attends the correct calendar.\"" },
  { zh: "朕之不德，不能弘覆。", literal: "My lack of virtue cannot broadly cover all.", idiomatic: "My lack of virtue cannot broadly shelter all." },
  { zh: "其以客禮待之，令單于位在諸侯王上，贊謁稱臣而不名。", literal: "Let him be received with guest ritual; order the chanyu's place above the feudal kings; at presentation let him be called subject but not by personal name.", idiomatic: "Let him be received with guest ritual; place the chanyu above the feudal kings; at presentation let him be called subject but not by personal name." },
  { zh: ":荀悅論曰：《春秋》之義，王者無外，欲一於天下也。", literal: ": Xun Yue's discussion says: The meaning of the Spring and Autumn Annals is that the king has no outside—he wishes oneness in All-under-Heaven.", idiomatic: ": Xun Yue's discussion says: The meaning of the Spring and Autumn Annals is that the king has no outside—he wishes oneness in All-under-Heaven." },
  { zh: "戎狄道理遼遠，人跡介絕，故正朔不及，禮教不加，非尊之也，其勢然也。", literal: "The Rong and Di lie on roads distant and far, human traces cut off; therefore the correct calendar does not reach them and ritual teaching is not applied—not because they are honored, but because the situation is so.", idiomatic: "The Rong and Di lie on roads distant and far, human traces cut off; therefore the correct calendar does not reach them and ritual teaching is not applied—not because they are honored, but because the situation is so." },
  { zh: "《詩》云：「自彼氐、羌，莫敢不來王。", literal: "The Odes says: \"From those Di and Qiang, none dares not come to court as king [tributary].", idiomatic: "The Odes says, \"From those Di and Qiang, none dares fail to come to court.\"" },
  { zh: "」故要、荒之君必奉王貢。", literal: "\" Therefore lords of the yao and huang domains must present royal tribute.", idiomatic: "\" Therefore lords of the outer and wild domains must present royal tribute." },
  { zh: "若不供職，則有辭讓號令加焉，非敵國之謂也。", literal: "If they do not perform their duties, then words of reproof and orders and commands are applied to them—not the meaning of rival state.", idiomatic: "If they do not perform their duties, reproof and orders are applied to them—they are not called rival states." },
  { zh: "望之欲待以不臣之禮，加之王公之上，僭度失序，以亂天常，非禮也！", literal: "Wangzhi wishing to receive him with the ritual of one not a subject and place him above kings and dukes transgresses degrees, loses order, and disorders the heavenly constancy—it is not ritual!", idiomatic: "Wangzhi's wish to receive him with the ritual of one not a subject and place him above kings and dukes transgresses proper rank, destroys order, and disorders the heavenly constancy—it is not ritual!" },
  { zh: "若以權時之宜，則異論矣。", literal: "If judged by the expedient fit of the time, then it is a different discussion.", idiomatic: "If judged by the expedient fit of the time, then it is a different matter." },
  { zh: "----9詔遣車騎都尉韓昌迎單于，發所過七郡二千騎為陳道上。", literal: "----9 An edict sent Commandant of Cavalry Han Chang to welcome the chanyu and dispatched two thousand cavalry from the seven commanderies along the route to form an escort on the road.", idiomatic: "----9 An edict sent Commandant of Cavalry Han Chang to welcome the chanyu and dispatched two thousand cavalry from the seven commanderies along the route to escort him on the road." },
  { zh: "1春，正月，上行幸甘泉，郊泰畤。", literal: "1 Spring, first month, the emperor travelled in favor to Ganquan and performed suburban sacrifice at Tai畤.", idiomatic: "1 In spring, the first month, the emperor travelled to Ganquan and performed suburban sacrifice at Tai畤." },
  { zh: "----2匈奴呼韓邪單于來朝，贊謁稱籓臣而不名。", literal: "----2 The Xiongnu Chanyu Huhanye came to court; at presentation he was called a vassal subject but not by personal name.", idiomatic: "----2 The Xiongnu chanyu Huhanye came to court; at presentation he was called a vassal subject but not by personal name." },
  { zh: "賜以冠帶、衣裳，黃金璽、盭綬，玉具劍、佩刀，弓一張，矢四發，棨戟十，安車一乘，鞍勒一具，馬十五匹，黃金二十斤，錢二十萬，衣被七十七襲，錦繡、綺縠、雜帛八千匹，絮六千斤。", literal: "He was granted cap and belt, robes, a golden seal and盭 ribbon, a jade-fitted sword and girdle knife, one bow, four arrows in a quiver, ten halberds with tassels, one cushioned carriage, one set of saddle and bridle, fifteen horses, twenty jin of gold, two hundred thousand cash, seventy-seven suits of clothing and coverlets, eight thousand bolts of brocade, damask, fine silk, and miscellaneous silks, and six thousand jin of wadding.", idiomatic: "He was granted cap and belt, robes, a golden seal and盭 ribbon, a jade-fitted sword and girdle knife, one bow, four arrows in a quiver, ten halberds with tassels, one cushioned carriage, one set of saddle and bridle, fifteen horses, twenty jin of gold, two hundred thousand cash, seventy-seven suits of clothing and coverlets, eight thousand bolts of brocade, damask, fine silk, and miscellaneous silks, and six thousand jin of wadding." },
  { zh: "禮畢，使使者道單于先行宿長平。", literal: "When the rites were finished, the emperor sent an envoy to escort the chanyu ahead to lodge at Changping.", idiomatic: "When the rites were finished, the emperor sent an envoy to escort the chanyu ahead to lodge at Changping." },
  { zh: "上自甘泉宿池陽宮。", literal: "The emperor himself, coming from Ganquan, lodged at Chiyang Palace.", idiomatic: "The emperor himself, coming from Ganquan, lodged at Chiyang Palace." },
  { zh: "上登長平阪，詔單于毋謁，其左右當戶群臣皆得列觀，及諸蠻夷君長、王、侯數萬，咸迎於渭橋下，夾道陳。", literal: "The emperor ascended Changping Slope and ordered that the chanyu need not pay audience; his attendants and the Household ministers at the gate all could stand in ranks to observe, and several tens of thousands of various barbarian chieftains, kings, and marquises all welcomed him below Wei Bridge, arrayed along both sides of the road.", idiomatic: "The emperor ascended Changping Slope and ordered that the chanyu need not pay audience; his attendants and the Household ministers at the gate all could stand in ranks to observe, and several tens of thousands of various barbarian chieftains, kings, and marquises all welcomed him below Wei Bridge, arrayed along both sides of the road." },
  { zh: "上登渭橋，咸稱萬歲。", literal: "The emperor mounted Wei Bridge; all called \"Ten thousand years!\"", idiomatic: "The emperor mounted Wei Bridge; all cried \"Long live the emperor!\"" },
  { zh: "單于就邸長安。", literal: "The chanyu arrived at his lodge in Chang'an.", idiomatic: "The chanyu arrived at his lodge in Chang'an." },
  { zh: "置酒建章宮，饗賜單于，觀以珍寶。", literal: "Wine was set out at Jianzhang Palace; the chanyu was feasted and gifted, and shown precious treasures.", idiomatic: "Wine was set out at Jianzhang Palace; the chanyu was feasted and gifted, and shown precious treasures." },
  { zh: "二月，遣單于歸國。", literal: "Second month, the chanyu was sent home to his state.", idiomatic: "In the second month, the chanyu was sent home to his state." },
  { zh: "單于自請「願留居幕南光祿塞下；", literal: "The chanyu himself requested: \"I wish to remain dwelling south of the curtain below Guanglu Pass;", idiomatic: "The chanyu himself requested, \"I wish to remain dwelling south of the curtain below Guanglu Pass;\"" },
  { zh: "有急，保漢受降城。", literal: "if there is an emergency, I may take refuge at the Han Surrender-Accepting Fortress.", idiomatic: "if there is an emergency, I may take refuge at the Han Surrender-Accepting Fortress.\"" },
  { zh: "」漢遣長樂衛尉、高昌侯董忠、車騎都尉韓昌將騎萬六千，又發邊郡士馬以千數，送單于出朔方雞鹿塞。", literal: "\" The Han sent Chief Commandant of Changle Wei Dong Zhong, Marquis of Gaochang, and Commandant of Cavalry Han Chang leading sixteen thousand cavalry, and also raised border commandery troops and horses by the thousands, to escort the chanyu out through Shuofang's Jilu Pass.", idiomatic: "\" The Han sent Chief Commandant of Changle Wei Dong Zhong, Marquis of Gaochang, and Commandant of Cavalry Han Chang leading sixteen thousand cavalry, and also raised border commandery troops and horses by the thousands, to escort the chanyu out through Shuofang's Jilu Pass." },
  { zh: "詔忠等留衛單于，助誅不服，又轉邊谷米糒，前後三萬四千斛，給贍其食。", literal: "An edict ordered Dong and the others to remain and guard the chanyu, help punish those who would not submit, and also forwarded border-grain rice and dried grain—thirty-four thousand hu in all—to supply his food.", idiomatic: "An edict ordered Dong and the others to remain and guard the chanyu, help punish those who would not submit, and also forwarded border-grain rice and dried grain—thirty-four thousand hu in all—to supply his food." },
  { zh: "先是，自烏孫以西至安息諸國近匈奴者，皆畏匈奴而輕漢，及呼韓邪單于朝漢後，咸尊漢矣。", literal: "Earlier, from Wusun west to Parthia, all states near the Xiongnu feared the Xiongnu and slighted the Han; after Chanyu Huhanye attended the Han court, all honored the Han.", idiomatic: "Earlier, from Wusun west to Parthia, all states near the Xiongnu feared the Xiongnu and slighted the Han; after Chanyu Huhanye attended the Han court, all honored the Han." },
  { zh: "上以戎狄賓服，思股肱之美，乃圖畫其人於麒麟閣，法其容貌，署其官爵、姓名。", literal: "The emperor, because the Rong and Di had come as guests and submitted, thought of the beauty of his chief ministers and therefore painted their likenesses in Qilin Pavilion, taking their appearances as models and inscribing their offices, ranks, and names.", idiomatic: "Because the Rong and Di had come as guests and submitted, the emperor thought of the worth of his chief ministers and had their likenesses painted in Qilin Pavilion, modeled on their appearances, with their offices, ranks, and names inscribed." },
  { zh: "唯霍光不名，曰「大司馬、大將軍、博陸候，姓霍氏」。", literal: "Only Huo Guang was not named by personal name; it read \"Grand Marshal, Grand General, Marquis of Bolu, surname Huo.\"", idiomatic: "Only Huo Guang was not named by personal name; the inscription read \"Grand Marshal, Grand General, Marquis of Bolu, surname Huo.\"" },
  { zh: "其次張安世、韓增、趙充國、魏相、丙吉、杜延年、劉德、梁丘賀、蕭望之、蘇武。", literal: "Next came Zhang Anshi, Han Zeng, Zhao Chongguo, Wei Xiang, Bing Ji, Du Yannian, Liu De, Liangqiu He, Xiao Wangzhi, and Su Wu.", idiomatic: "Next came Zhang Anshi, Han Zeng, Zhao Chongguo, Wei Xiang, Bing Ji, Du Yannian, Liu De, Liangqiu He, Xiao Wangzhi, and Su Wu." },
  { zh: "凡十一人，皆有功德，知名當世，是以表而揚之，明著中興輔佐，列於方叔、召虎、仲山甫焉。", literal: "Eleven in all had merit and achievement and were renowned in their age; therefore they were displayed and exalted, clearly showing the restoration-era assistants, ranked with Fang Shu, Duke of Shao, and Zhong Shanfu.", idiomatic: "Eleven in all had merit and achievement and were renowned in their age; therefore they were displayed and exalted, clearly showing the restoration-era assistants, ranked with Fang Shu, Duke of Shao, and Zhong Shanfu." },
  { zh: "----3鳳皇集新蔡。", literal: "----3 A phoenix gathered at Xincai.", idiomatic: "----3 A phoenix gathered at Xincai." },
  { zh: "----4三月，己巳、建成安侯黃霸薨。", literal: "----4 Third month, on jisi, Marquis An of Jiancheng Huang Ba passed away.", idiomatic: "----4 In the third month, on jisi, Marquis An of Jiancheng Huang Ba died." },
  { zh: "五月，甲午，-{于定國}-為丞相，封西平侯。", literal: "Fifth month, on jiawu, -{Yu Dingguo}- became chancellor and was enfeoffed as Marquis of Xiping.", idiomatic: "In the fifth month, on jiawu, -{Yu Dingguo}- became chancellor and was enfeoffed as Marquis of Xiping." },
  { zh: "太僕沛郡陳萬年為御史大夫。", literal: "Director of the Imperial Stud Chen Wannian of Pei Commandery became censor-in-chief.", idiomatic: "Director of the Imperial Stud Chen Wannian of Pei Commandery became censor-in-chief." },
  { zh: "----5詔諸儒講五經同異，蕭望之等平奏其議，上帝稱制臨決焉。", literal: "----5 An edict ordered the various Confucians to discuss the agreements and differences of the Five Classics; Xiao Wangzhi and others fairly reported their deliberations, and the emperor personally decided by imperial pronouncement.", idiomatic: "----5 An edict ordered the various Confucians to discuss the agreements and differences of the Five Classics; Xiao Wangzhi and others fairly reported their deliberations, and the emperor personally decided by imperial pronouncement." },
  { zh: "乃立梁丘《易》、大、小夏侯《尚書》、《穀梁春秋》博士。", literal: "Thereupon erudites were established for Liangqiu's Changes, the Great and Little Xiahou Documents, and the Guliang Spring and Autumn.", idiomatic: "Thereupon erudites were established for Liangqiu's Changes, the Great and Little Xiahou Documents, and the Guliang Spring and Autumn." },
  { zh: "----6烏孫大昆彌元貴靡及鴟靡皆病死。", literal: "----6 Wusun Great Kunmi Yuan Guimie and Chimi both died of illness.", idiomatic: "----6 Wusun Great Kunmi Yuan Guimie and Chimi both died of illness." },
  { zh: "公主上書言：「年老土思，願得歸骸骨，葬漢地！", literal: "The princess submitted a memorial saying: \"I am old and homesick for my native soil; I wish to have my bones returned and buried in Han territory!", idiomatic: "The princess submitted a memorial saying, \"I am old and homesick for my native soil; I wish to have my bones returned and buried in Han territory!\"" },
  { zh: "」天子閔而迎之。", literal: "\" The Son of Heaven pitied her and welcomed her back.", idiomatic: "\" The emperor pitied her and welcomed her back." },
  { zh: "冬，至京師，待之一如公主之制。", literal: "Winter, she reached the capital and was treated entirely according to princess rites.", idiomatic: "In winter she reached the capital and was treated entirely according to princess rites." },
  { zh: "後二歲卒。", literal: "Two years later she died.", idiomatic: "Two years later she died." },
  { zh: "----7元貴靡子星靡代為大昆彌，弱。", literal: "----7 Yuan Guimie's son Xingmie succeeded as Great Kunmi; he was weak.", idiomatic: "----7 Yuan Guimie's son Xingmie succeeded as Great Kunmi; he was weak." },
  { zh: "馮夫人上書：「願使烏孫，鎮撫星靡。", literal: "Lady Feng submitted a memorial: \"I wish to be sent to Wusun to pacify and comfort Xingmie.", idiomatic: "Lady Feng submitted a memorial: \"I wish to be sent to Wusun to pacify and comfort Xingmie.\"" },
  { zh: "」漢遣之。", literal: "\" The Han sent her.", idiomatic: "\" The Han sent her." },
  { zh: "都護韓宣奏烏孫大吏大祿、大監皆可賜以金印紫綬，以尊輔大昆彌。", literal: "Protector General Han Xuan memorialized that Wusun's great administrator Dalu and great supervisor could both be granted gold seals and purple ribbons to honor and assist the Great Kunmi.", idiomatic: "Protector General Han Xuan memorialized that Wusun's great administrator Dalu and great supervisor could both be granted gold seals and purple ribbons to honor and assist the Great Kunmi." },
  { zh: "漢許之。", literal: "The Han granted this.", idiomatic: "The Han granted this." },
  { zh: "其後段會宗為都護，乃招還亡叛，安定之。", literal: "Afterward Duan Huizong became protector general; he then summoned back deserters and rebels and pacified the state.", idiomatic: "Afterward Duan Huizong became protector general; he then summoned back deserters and rebels and pacified the state." },
  { zh: "星靡死，子雌栗靡代立。", literal: "Xingmie died; his son Ciliqimie succeeded to the throne.", idiomatic: "Xingmie died; his son Ciliqimie succeeded to the throne." },
  { zh: "----8皇太子所幸司馬良娣病，且死，謂太子曰：「妾死非天命，乃諸娣妾、良人更祝詛殺我。", literal: "----8 The crown prince's favored Lady of the Chief of Cavalry Liang was ill and near death; she told the crown prince: \"My death is not Heaven's decree—it is the various secondary consorts and ladies who by turns prayed and cursed me to death.", idiomatic: "----8 The crown prince's favored Lady of the Chief of Cavalry Liang was ill and near death; she told the crown prince, \"My death is not Heaven's decree—it is the various secondary consorts and ladies who by turns prayed and cursed me to death.\"" },
  { zh: "」太子以為然。", literal: "\" The crown prince believed it.", idiomatic: "\" The crown prince believed it." },
  { zh: "及死，太子悲恚發病，忽忽不樂。", literal: "When she died, the crown prince grieved and fell ill, restless and joyless.", idiomatic: "When she died, the crown prince grieved and fell ill, restless and joyless." },
  { zh: "帝乃令皇后擇後宮家人子可以娛侍太子者，得元城王政君，送太子宮。", literal: "The emperor then ordered the empress to choose from the palace women of good family one who could divert and attend the crown prince; Wang Zhengjun of Yuancheng was obtained and sent to the crown prince's palace.", idiomatic: "The emperor then ordered the empress to choose from the palace women of good family one who could divert and attend the crown prince; Wang Zhengjun of Yuancheng was obtained and sent to the crown prince's palace." },
  { zh: "政君，故繡衣御史賀之孫女也，見於丙殿。", literal: "Zhengjun was the granddaughter of the former Embroidered-Robe Censor He and had been seen in the Bing Hall.", idiomatic: "Zhengjun was the granddaughter of the former Embroidered-Robe Censor He and had been seen in the Bing Hall." },
  { zh: "壹幸，有身。", literal: "Once favored, she became pregnant.", idiomatic: "Once favored, she became pregnant." },
  { zh: "是歲，生成帝於甲館畫堂，為世縕皇孫。", literal: "That year she gave birth to Emperor Cheng in the Painted Hall of the Jia Lodge; he was made heir-apparent great-grandson in the womb belt.", idiomatic: "That year she gave birth to Emperor Cheng in the Painted Hall of the Jia Lodge; he was made heir-apparent great-grandson in the womb belt." },
  { zh: "帝愛之，自名曰驁，字大孫，常置左右。", literal: "The emperor loved him, personally named him Ao, styled Dasun, and often kept him at his side.", idiomatic: "The emperor loved him, personally named him Ao, styled Dasun, and often kept him at his side." },
  { zh: "1夏，廣川王海陽坐禽獸行、賊殺不辜，廢，徙房陵。", literal: "1 Summer, King Haiyang of Guangchuan was charged with beastlike conduct and murdering the innocent; he was deposed and moved to Fangling.", idiomatic: "1 In summer, King Haiyang of Guangchuan was charged with beastlike conduct and murdering the innocent; he was deposed and moved to Fangling." },
  { zh: "----2冬，十月，丁卯，未央宮宣室閣火。", literal: "----2 Winter, tenth month, on dingmao, the Xuanshi Pavilion of Weiyang Palace caught fire.", idiomatic: "----2 In winter, the tenth month, on dingmao, the Xuanshi Pavilion of Weiyang Palace caught fire." },
  { zh: "----3是歲，徙定陶王囂為楚王。", literal: "----3 That year, King Xiao of Dingtao was moved to become King of Chu.", idiomatic: "----3 That year, King Xiao of Dingtao was moved to become King of Chu." },
  { zh: "----4匈奴呼韓邪、郅支兩單于俱遣使朝獻，漢待呼韓邪使有加焉。", literal: "----4 Both the Xiongnu chanyus Huhanye and Zhizhi sent envoys with tribute to court; the Han treated Huhanye's envoy with special favor.", idiomatic: "----4 Both the Xiongnu chanyus Huhanye and Zhizhi sent envoys with tribute to court; the Han treated Huhanye's envoy with special favor." },
  { zh: "1春，正月，上行幸甘泉，郊泰畤。", literal: "1 Spring, first month, the emperor travelled in favor to Ganquan and performed suburban sacrifice at Tai畤.", idiomatic: "1 In spring, the first month, the emperor travelled to Ganquan and performed suburban sacrifice at Tai畤." },
  { zh: "----2匈奴呼韓邪單于來朝；", literal: "----2 The Xiongnu Chanyu Huhanye came to court;", idiomatic: "----2 The Xiongnu chanyu Huhanye came to court;" },
  { zh: "二月，歸國。", literal: "second month, he returned to his state.", idiomatic: "in the second month he returned to his state." },
  { zh: "始，郅支單于以為呼韓邪兵弱，降漢，不能復自還，即引其眾西，欲攻定右地。", literal: "At the beginning, Chanyu Zhizhi thought Huhanye's troops were weak, that having submitted to the Han he could not return on his own; he therefore led his masses west, intending to attack and secure the right territory.", idiomatic: "At the beginning, Chanyu Zhizhi thought Huhanye's troops were weak and that, having submitted to the Han, he could not return on his own; he therefore led his followers west, intending to attack and secure the right territory." },
  { zh: "又屠耆單于小弟本侍呼韓邪，亦亡之右地，收兩兄餘兵，得數千人，自立為伊利目單于；", literal: "Also the younger brother of Chanyu Rizhi, who had originally served Huhanye, also fled to the right territory, gathered the remnant troops of his two elder brothers, obtained several thousand men, and established himself as Chanyu Yilimu;", idiomatic: "Also the younger brother of Chanyu Rizhi, who had originally served Huhanye, also fled to the right territory, gathered the remnant troops of his two elder brothers, obtained several thousand men, and established himself as Chanyu Yilimu;" },
  { zh: "道逢郅支，合戰，郅支殺之，併其兵五萬餘人。", literal: "on the road he met Zhizhi; they joined battle, Zhizhi killed him, and merged his troops to more than fifty thousand men.", idiomatic: "on the road he met Zhizhi; they joined battle, Zhizhi killed him, and merged his troops to more than fifty thousand men." },
  { zh: "郅支聞漢出兵谷助呼韓邪，即遂留居右地；", literal: "Zhizhi heard the Han had sent troops through the valley to help Huhanye and thereupon remained dwelling in the right territory;", idiomatic: "Zhizhi heard the Han had sent troops through the valley to help Huhanye and thereupon remained dwelling in the right territory;" },
  { zh: "自度力不能定匈奴，乃益西，近烏孫，欲與並力，遣使見小昆彌烏就屠。", literal: "judging for himself that his strength could not settle the Xiongnu, he went further west, drew near Wusun, wished to combine forces, and sent an envoy to see the Little Kunmi Wujiutu.", idiomatic: "judging for himself that his strength could not settle the Xiongnu, he went further west, drew near Wusun, wished to combine forces, and sent an envoy to see the Little Kunmi Wujiutu." },
  { zh: "烏就屠殺其使，發八千騎迎郅支。", literal: "Wujiutu killed his envoy and sent eight thousand cavalry to welcome Zhizhi.", idiomatic: "Wujiutu killed his envoy and sent eight thousand cavalry to welcome Zhizhi." },
  { zh: "郅支覺其謀，勒兵逢擊烏孫，破之；", literal: "Zhizhi perceived the plot, led his troops to meet and strike Wusun, and broke them;", idiomatic: "Zhizhi perceived the plot, led his troops to meet and strike Wusun, and defeated them;" },
  { zh: "因北擊烏揭、堅昆、丁令、並三國。", literal: "thereupon he struck north against the Wujie, Jiankun, and Dingling and annexed the three states.", idiomatic: "thereupon he struck north against the Wujie, Jiankun, and Dingling and annexed the three states." },
  { zh: "數遣兵擊烏孫，常勝之。", literal: "He repeatedly sent troops to attack Wusun and was often victorious.", idiomatic: "He repeatedly sent troops to attack Wusun and was often victorious." },
  { zh: "堅昆東去單于庭七千里，南去車師五千里，郅支留都之。", literal: "Jiankun lay seven thousand li east of the chanyu court and five thousand li south of Cheshi; Zhizhi remained and made it his capital.", idiomatic: "Jiankun lay seven thousand li east of the chanyu court and five thousand li south of Cheshi; Zhizhi remained and made it his capital." },
  { zh: "----3三月，有星孛於王良、閣道，入紫微宮。", literal: "----3 Third month, a comet appeared at Wangliang and Jiandao and entered the Purple Forbidden Palace.", idiomatic: "----3 In the third month, a comet appeared at Wangliang and Jiandao and entered the Purple Forbidden Palace." },
  { zh: "----4帝寢疾，選大臣可屬者，引外屬侍中樂陵侯史高、太子太傅蕭望之、少傅周堪至禁中，拜高為大司馬、車騎將軍，望之為前將軍、光祿勳，堪為光祿大夫，皆受遺詔輔政，領尚書事。", literal: "----4 The emperor lay ill in bed and chose ministers to whom he could entrust affairs; he summoned the related-by-marriage Attendant-in-Ordinary Marquis of Leling Shi Gao, tutor of the heir apparent Xiao Wangzhi, and junior tutor Zhou Kan to the inner palace, appointed Gao grand marshal and general of chariots and cavalry, Wangzhi forward general and director of the imperial secretariat, and Kan director of the masters of writing—all received the testamentary edict to assist in government and headed Secretariat affairs.", idiomatic: "----4 The emperor lay gravely ill and chose ministers to whom he could entrust affairs; he summoned the related-by-marriage Attendant-in-Ordinary Marquis of Leling Shi Gao, Tutor of the Heir Apparent Xiao Wangzhi, and Junior Tutor Zhou Kan to the inner palace, appointed Gao grand marshal and general of chariots and cavalry, Wangzhi forward general and director of the imperial secretariat, and Kan director of the masters of writing—all received the testamentary edict to assist in government and headed Secretariat affairs." },
  { zh: "冬，十二月，甲戌，帝崩於未央宮。", literal: "Winter, twelfth month, on jiaxu, the emperor died at Weiyang Palace.", idiomatic: "In winter, the twelfth month, on jiaxu, the emperor died at Weiyang Palace." },
  { zh: ":班固贊曰：孝宣之治，信賞必罰，綜核名實。", literal: ": Ban Gu's praise says: The governance of Emperor Xiaoxuan—rewards and punishments were sure, names and realities were comprehensively verified.", idiomatic: ": Ban Gu's praise says: The governance of Emperor Xiaoxuan—rewards and punishments were sure, names and realities were comprehensively verified." },
  { zh: "政事、文學、法理之士，鹹精其能。", literal: "Men of government affairs, letters, and legal principle all refined their abilities.", idiomatic: "Men of government affairs, letters, and legal principle all refined their abilities." },
  { zh: "至於技巧、工匠、器械，自元、成間鮮能及之。", literal: "As for skill, craftsmen, and instruments—from the Yuan and Cheng reigns few could match it.", idiomatic: "As for skill, craftsmen, and instruments—from the Yuan and Cheng reigns few could match it." },
  { zh: "亦足以知吏稱其職，民安其業也。", literal: "This too is enough to know that officials claimed their posts and the people were secure in their livelihoods.", idiomatic: "This too is enough to know that officials claimed their posts and the people were secure in their livelihoods." },
  { zh: "遭值匈奴乖亂，推亡固存，信威北夷，單于慕義，稽首稱籓。", literal: "He encountered the Xiongnu in disorder, pushed the perishing and secured what remained, his trust and might reached the northern Yi; the chanyu admired his righteousness and bowed, calling himself vassal.", idiomatic: "He encountered the Xiongnu in disorder, pushed the perishing and secured what remained, his trust and might reached the northern Yi; the chanyu admired his righteousness and bowed, calling himself vassal." },
  { zh: "功光祖宗，業垂後嗣，可謂中興，侔德殷宗、周宣矣！", literal: "His merit illumined the ancestors and his enterprise hangs for posterity; it can be called a restoration, equal in virtue to the Yin Ancestor and King Xuan of Zhou!", idiomatic: "His merit illumined the ancestors and his enterprise hangs for posterity; it can be called a restoration, equal in virtue to the Yin Ancestor and King Xuan of Zhou!" },
  { zh: "----5癸巳，太子即皇帝位，謁高廟，尊皇太后曰太皇太后，皇后曰皇太后。", literal: "----5 On guisi, the crown prince assumed the imperial throne, visited Gaozu's temple, and honored the empress dowager as Grand Empress Dowager and the empress as Empress Dowager.", idiomatic: "----5 On guisi, the crown prince assumed the imperial throne, visited Gaozu's temple, and honored the empress dowager as Grand Empress Dowager and the empress as Empress Dowager." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
